insert into public.frases_aplicadas (palavra_id, nivel, pt, en, de, it) values
  (1, 1, 'Oi, mamãe!', 'Hi, Mom!', 'Hallo, Mama!', 'Ciao, mamma!'),
  (1, 2, 'Oi, vovó, que bom te ver!', 'Hi, Grandma, it''s good to see you!', 'Hallo, Oma, schön, dich zu sehen!', 'Ciao, nonna, che bello vederti!'),
  (2, 1, 'Bom dia, papai!', 'Good morning, Dad!', 'Guten Morgen, Papa!', 'Buongiorno, papà!'),
  (2, 2, 'Bom dia! O sol já acordou.', 'Good morning! The sun is already up.', 'Guten Morgen! Die Sonne ist schon wach.', 'Buongiorno! Il sole è già sveglio.'),
  (3, 1, 'Boa noite, mamãe.', 'Good night, Mom.', 'Gute Nacht, Mama.', 'Buonanotte, mamma.'),
  (3, 2, 'Boa noite, ursinho, agora vamos dormir.', 'Good night, teddy, now let''s go to sleep.', 'Gute Nacht, Teddy, jetzt schlafen wir.', 'Buonanotte, orsacchiotto, adesso dormiamo.'),
  (4, 1, 'Obrigado, vovô!', 'Thank you, Grandpa!', 'Danke, Opa!', 'Grazie, nonno!'),
  (4, 2, 'Obrigado pelo presente bonito!', 'Thank you for the nice present!', 'Danke für das schöne Geschenk!', 'Grazie per il bel regalo!'),
  (5, 1, 'Água, por favor.', 'Water, please.', 'Wasser, bitte.', 'Acqua, per favore.'),
  (5, 2, 'Mamãe, me dá um biscoito, por favor?', 'Mom, can I have a cookie, please?', 'Mama, kann ich bitte einen Keks haben?', 'Mamma, mi dai un biscotto, per favore?'),
  (6, 1, 'Tchau, papai!', 'Bye, Dad!', 'Tschüss, Papa!', 'Ciao, papà!'),
  (6, 2, 'Tchau, amigos, até amanhã na escola!', 'Bye, friends, see you tomorrow at school!', 'Tschüss, Freunde, bis morgen in der Schule!', 'Ciao, amici, a domani a scuola!'),
  (73, 1, 'Adeus, passarinho!', 'Goodbye, little bird!', 'Auf Wiedersehen, kleiner Vogel!', 'Arrivederci, uccellino!'),
  (73, 2, 'Adeus, praia, a gente volta no verão!', 'Goodbye, beach, we''ll come back in summer!', 'Auf Wiedersehen, Strand, wir kommen im Sommer wieder!', 'Arrivederci, spiaggia, torniamo in estate!'),
  (74, 1, 'Até logo, vovó!', 'See you later, Grandma!', 'Bis später, Oma!', 'A dopo, nonna!'),
  (74, 2, 'Até logo, eu volto depois do almoço.', 'See you later, I''ll be back after lunch.', 'Bis später, ich komme nach dem Mittagessen zurück.', 'A dopo, torno dopo pranzo.'),
  (75, 1, 'Até amanhã, professora!', 'See you tomorrow, teacher!', 'Bis morgen, liebe Lehrerin!', 'A domani, maestra!'),
  (75, 2, 'Até amanhã! Amanhã a gente brinca de novo.', 'See you tomorrow! Tomorrow we''ll play again.', 'Bis morgen! Morgen spielen wir wieder.', 'A domani! Domani giochiamo ancora.'),
  (76, 1, 'Até já, mamãe!', 'See you soon, Mom!', 'Bis bald, Mama!', 'A presto, mamma!'),
  (76, 2, 'Até já, vou só pegar meu casaco.', 'See you soon, I''m just getting my coat.', 'Bis bald, ich hole nur schnell meinen Mantel.', 'A presto, prendo solo il mio cappotto.'),
  (77, 1, 'Até mais, pessoal!', 'See you around, everyone!', 'Man sieht sich, Leute!', 'Ci vediamo, ragazzi!'),
  (77, 2, 'Até mais, foi muito divertido brincar com vocês!', 'See you around, it was so much fun playing with you!', 'Man sieht sich, es hat viel Spaß gemacht, mit euch zu spielen!', 'Ci vediamo, è stato bellissimo giocare con voi!'),
  (78, 1, 'Volte logo, papai!', 'Come back soon, Dad!', 'Komm bald wieder, Papa!', 'Torna presto, papà!'),
  (78, 2, 'Volte logo, vovô, eu vou sentir saudade.', 'Come back soon, Grandpa, I will miss you.', 'Komm bald wieder, Opa, ich werde dich vermissen.', 'Torna presto, nonno, mi mancherai.'),
  (79, 1, 'Um beijo para você, mamãe!', 'A kiss for you, Mom!', 'Ein Kuss für dich, Mama!', 'Un bacio per te, mamma!'),
  (79, 2, 'Eu dou um beijo no bebê antes de dormir.', 'I give the baby a kiss before bedtime.', 'Ich gebe dem Baby vor dem Schlafen einen Kuss.', 'Do un bacio al bambino prima di dormire.'),
  (80, 1, 'Um abraço para você, vovó!', 'A hug for you, Grandma!', 'Eine Umarmung für dich, Oma!', 'Un abbraccio per te, nonna!'),
  (80, 2, 'Quando eu fico triste, um abraço me ajuda.', 'When I feel sad, a hug helps me.', 'Wenn ich traurig bin, hilft mir eine Umarmung.', 'Quando sono triste, un abbraccio mi aiuta.'),
  (81, 1, 'Durma bem, bebê.', 'Sleep well, baby.', 'Schlaf gut, Baby.', 'Dormi bene, piccolo.'),
  (81, 2, 'Durma bem e sonhe com as estrelas.', 'Sleep well and dream of the stars.', 'Schlaf gut und träum von den Sternen.', 'Dormi bene e sogna le stelle.'),
  (82, 1, 'Bom descanso, vovô.', 'Rest well, Grandpa.', 'Gute Erholung, Opa.', 'Buon riposo, nonno.'),
  (82, 2, 'Bom descanso, amanhã a gente vai ao parque.', 'Rest well, tomorrow we''re going to the park.', 'Gute Erholung, morgen gehen wir in den Park.', 'Buon riposo, domani andiamo al parco.'),
  (83, 1, 'Boa viagem, titia!', 'Have a good trip, Auntie!', 'Gute Reise, Tante!', 'Buon viaggio, zia!'),
  (83, 2, 'Boa viagem! Mande uma foto do avião.', 'Have a good trip! Send a picture of the plane.', 'Gute Reise! Schick ein Foto vom Flugzeug.', 'Buon viaggio! Manda una foto dell''aereo.'),
  (84, 1, 'Boa sorte, amigo!', 'Good luck, friend!', 'Viel Glück, mein Freund!', 'Buona fortuna, amico!'),
  (84, 2, 'Boa sorte no jogo de futebol hoje!', 'Good luck at the soccer game today!', 'Viel Glück heute beim Fußballspiel!', 'Buona fortuna per la partita di calcio di oggi!'),
  (85, 1, 'Se cuida, vovó!', 'Take care, Grandma!', 'Pass auf dich auf, Oma!', 'Stammi bene, nonna!'),
  (85, 2, 'Se cuida e veste o casaco, está frio.', 'Take care and put on your coat, it''s cold.', 'Pass auf dich auf und zieh den Mantel an, es ist kalt.', 'Stammi bene e mettiti il cappotto, fa freddo.'),
  (86, 1, 'Tenha um bom dia, papai!', 'Have a good day, Dad!', 'Schönen Tag, Papa!', 'Buona giornata, papà!'),
  (86, 2, 'Tenha um bom dia no trabalho, mamãe!', 'Have a good day at work, Mom!', 'Schönen Tag bei der Arbeit, Mama!', 'Buona giornata al lavoro, mamma!'),
  (87, 1, 'Bom fim de semana, professora!', 'Have a good weekend, teacher!', 'Schönes Wochenende, liebe Lehrerin!', 'Buon fine settimana, maestra!'),
  (87, 2, 'Bom fim de semana! Vamos brincar no parque.', 'Have a good weekend! Let''s play in the park.', 'Schönes Wochenende! Lass uns im Park spielen.', 'Buon fine settimana! Andiamo a giocare al parco.'),
  (7, 1, 'Eu amo a mamãe.', 'I love Mom.', 'Ich hab Mama lieb.', 'Voglio bene alla mamma.'),
  (7, 2, 'A mamãe lê uma história antes de dormir.', 'Mom reads a story before bedtime.', 'Mama liest vor dem Schlafen eine Geschichte vor.', 'La mamma legge una storia prima di dormire.'),
  (8, 1, 'O papai está aqui.', 'Dad is here.', 'Papa ist hier.', 'Papà è qui.'),
  (8, 2, 'O papai me leva ao parque no domingo.', 'Dad takes me to the park on Sunday.', 'Papa geht am Sonntag mit mir in den Park.', 'Papà mi porta al parco la domenica.'),
  (9, 1, 'A vovó faz bolo.', 'Grandma makes cake.', 'Oma backt Kuchen.', 'La nonna fa la torta.'),
  (9, 2, 'A vovó faz um bolo de chocolate para mim.', 'Grandma makes a chocolate cake for me.', 'Oma backt einen Schokoladenkuchen für mich.', 'La nonna fa una torta al cioccolato per me.'),
  (10, 1, 'O vovô canta comigo.', 'Grandpa sings with me.', 'Opa singt mit mir.', 'Il nonno canta con me.'),
  (10, 2, 'O vovô conta histórias engraçadas no jardim.', 'Grandpa tells funny stories in the garden.', 'Opa erzählt im Garten lustige Geschichten.', 'Il nonno racconta storie divertenti in giardino.'),
  (11, 1, 'O bebê está dormindo.', 'The baby is sleeping.', 'Das Baby schläft.', 'Il bambino dorme.'),
  (11, 2, 'O bebê ri quando eu faço uma careta.', 'The baby laughs when I make a funny face.', 'Das Baby lacht, wenn ich eine Grimasse mache.', 'Il bambino ride quando faccio una smorfia.'),
  (12, 1, 'Eu amo minha família.', 'I love my family.', 'Ich liebe meine Familie.', 'Amo la mia famiglia.'),
  (12, 2, 'Minha família janta junto todas as noites.', 'My family has dinner together every night.', 'Meine Familie isst jeden Abend zusammen.', 'La mia famiglia cena insieme ogni sera.'),
  (13, 1, 'Toque na cabeça.', 'Touch your head.', 'Fass deinen Kopf an.', 'Toccati la testa.'),
  (13, 2, 'Eu uso um chapéu na cabeça quando faz sol.', 'I wear a hat on my head when it''s sunny.', 'Ich trage einen Hut auf dem Kopf, wenn die Sonne scheint.', 'Porto un cappello in testa quando c''è il sole.'),
  (14, 1, 'Eu penteio o cabelo.', 'I comb my hair.', 'Ich kämme meine Haare.', 'Mi pettino i capelli.'),
  (14, 2, 'Depois do banho, a mamãe seca meu cabelo.', 'After the bath, Mom dries my hair.', 'Nach dem Baden föhnt Mama meine Haare.', 'Dopo il bagno, la mamma mi asciuga i capelli.'),
  (15, 1, 'Eu fecho um olho.', 'I close one eye.', 'Ich mache ein Auge zu.', 'Chiudo un occhio.'),
  (15, 2, 'O gato tem um olho verde e um olho azul.', 'The cat has one green eye and one blue eye.', 'Die Katze hat ein grünes Auge und ein blaues Auge.', 'Il gatto ha un occhio verde e un occhio blu.'),
  (16, 1, 'O coelho tem orelhas compridas.', 'The rabbit has long ears.', 'Der Hase hat lange Ohren.', 'Il coniglio ha le orecchie lunghe.'),
  (16, 2, 'O cachorro levanta a orelha quando ouve um barulho.', 'The dog lifts its ear when it hears a noise.', 'Der Hund stellt das Ohr auf, wenn er ein Geräusch hört.', 'Il cane alza l''orecchio quando sente un rumore.'),
  (17, 1, 'O palhaço tem nariz vermelho.', 'The clown has a red nose.', 'Der Clown hat eine rote Nase.', 'Il pagliaccio ha il naso rosso.'),
  (17, 2, 'Eu cheiro a flor com o meu nariz.', 'I smell the flower with my nose.', 'Ich rieche mit meiner Nase an der Blume.', 'Annuso il fiore con il mio naso.'),
  (18, 1, 'Abra a boca.', 'Open your mouth.', 'Mach den Mund auf.', 'Apri la bocca.'),
  (18, 2, 'Eu escovo os dentes e lavo a boca com água.', 'I brush my teeth and rinse my mouth with water.', 'Ich putze die Zähne und spüle den Mund mit Wasser aus.', 'Lavo i denti e sciacquo la bocca con l''acqua.'),
  (19, 1, 'Meu dente caiu.', 'My tooth fell out.', 'Mein Zahn ist rausgefallen.', 'Mi è caduto un dente.'),
  (19, 2, 'Eu escovo cada dente depois do café da manhã.', 'I brush every tooth after breakfast.', 'Ich putze nach dem Frühstück jeden Zahn.', 'Lavo ogni dente dopo la colazione.'),
  (20, 1, 'O cachorro mostra a língua.', 'The dog sticks out its tongue.', 'Der Hund streckt die Zunge raus.', 'Il cane tira fuori la lingua.'),
  (20, 2, 'O sorvete gelado faz cócegas na minha língua.', 'The cold ice cream tickles my tongue.', 'Das kalte Eis kitzelt meine Zunge.', 'Il gelato freddo mi fa il solletico sulla lingua.'),
  (21, 1, 'Levante o braço.', 'Raise your arm.', 'Heb den Arm hoch.', 'Alza il braccio.'),
  (21, 2, 'O papai me leva no braço até a cama.', 'Dad carries me in his arm to bed.', 'Papa trägt mich auf dem Arm ins Bett.', 'Papà mi porta in braccio fino al letto.'),
  (22, 1, 'Me dá a mão.', 'Give me your hand.', 'Gib mir die Hand.', 'Dammi la mano.'),
  (22, 2, 'Eu seguro a mão da mamãe para atravessar a rua.', 'I hold Mom''s hand to cross the street.', 'Ich halte Mamas Hand, wenn wir über die Straße gehen.', 'Tengo la mano della mamma per attraversare la strada.'),
  (23, 1, 'Eu conto com o dedo.', 'I count with my finger.', 'Ich zähle mit dem Finger.', 'Conto con il dito.'),
  (23, 2, 'A joaninha subiu no meu dedo e depois voou.', 'The ladybug climbed onto my finger and then flew away.', 'Der Marienkäfer krabbelt auf meinen Finger und fliegt dann weg.', 'La coccinella sale sul mio dito e poi vola via.'),
  (24, 1, 'A girafa tem pernas compridas.', 'The giraffe has long legs.', 'Die Giraffe hat lange Beine.', 'La giraffa ha le gambe lunghe.'),
  (24, 2, 'Eu pulo numa perna só, como um flamingo.', 'I hop on one leg, like a flamingo.', 'Ich hüpfe auf einem Bein, wie ein Flamingo.', 'Salto su una gamba sola, come un fenicottero.'),
  (25, 1, 'Eu chuto com o pé.', 'I kick with my foot.', 'Ich kicke den Ball mit dem Fuß.', 'Calcio con il piede.'),
  (25, 2, 'A areia da praia faz cócegas no meu pé.', 'The sand on the beach tickles my foot.', 'Der Sand am Strand kitzelt meinen Fuß.', 'La sabbia della spiaggia mi fa il solletico sul piede.'),
  (26, 1, 'Meu joelho dói.', 'My knee hurts.', 'Mein Knie tut weh.', 'Mi fa male il ginocchio.'),
  (26, 2, 'O vovô dobra o joelho para amarrar o sapato.', 'Grandpa bends his knee to tie his shoe.', 'Opa beugt das Knie, um seinen Schuh zu binden.', 'Il nonno piega il ginocchio per allacciarsi la scarpa.'),
  (27, 1, 'Minha barriga está cheia.', 'My belly is full.', 'Mein Bauch ist voll.', 'La mia pancia è piena.'),
  (27, 2, 'Depois do almoço, o gato dorme de barriga para cima.', 'After lunch, the cat sleeps belly up.', 'Nach dem Mittagessen schläft die Katze mit dem Bauch nach oben.', 'Dopo pranzo, il gatto dorme a pancia in su.'),
  (429, 1, 'Eu lavo o rosto.', 'I wash my face.', 'Ich wasche mein Gesicht.', 'Mi lavo il viso.'),
  (429, 2, 'O palhaço pintou o rosto de muitas cores.', 'The clown painted his face in many colors.', 'Der Clown hat sein Gesicht bunt angemalt.', 'Il pagliaccio si è dipinto il viso di tanti colori.'),
  (430, 1, 'A mamãe beija minha testa.', 'Mom kisses my forehead.', 'Mama küsst meine Stirn.', 'La mamma mi bacia la fronte.'),
  (430, 2, 'Quando eu tenho febre, minha testa fica quente.', 'When I have a fever, my forehead gets hot.', 'Wenn ich Fieber habe, wird meine Stirn heiß.', 'Quando ho la febbre, la mia fronte diventa calda.'),
  (431, 1, 'O vovô tem sobrancelhas brancas.', 'Grandpa has white eyebrows.', 'Opa hat weiße Augenbrauen.', 'Il nonno ha le sopracciglia bianche.'),
  (431, 2, 'O papai levanta a sobrancelha quando fica surpreso.', 'Dad raises his eyebrow when he is surprised.', 'Papa hebt die Augenbraue, wenn er überrascht ist.', 'Papà alza il sopracciglio quando è sorpreso.'),
  (432, 1, 'Caiu um cílio.', 'An eyelash fell out.', 'Eine Wimper ist ausgefallen.', 'È caduto un ciglio.'),
  (432, 2, 'Faça um pedido e sopre o cílio da bochecha.', 'Make a wish and blow the eyelash off your cheek.', 'Wünsch dir etwas und puste die Wimper von der Wange.', 'Esprimi un desiderio e soffia via il ciglio dalla guancia.'),
  (433, 1, 'O bebê tem bochechas redondas.', 'The baby has round cheeks.', 'Das Baby hat runde Wangen.', 'Il bambino ha le guance tonde.'),
  (433, 2, 'A vovó aperta minha bochecha e dá risada.', 'Grandma pinches my cheek and laughs.', 'Oma kneift mich in die Wange und lacht.', 'La nonna mi pizzica la guancia e ride.'),
  (434, 1, 'O vovô tem barba no queixo.', 'Grandpa has a beard on his chin.', 'Opa hat einen Bart am Kinn.', 'Il nonno ha la barba sul mento.'),
  (434, 2, 'Quando eu penso, eu coloco a mão no queixo.', 'When I think, I put my hand on my chin.', 'Wenn ich nachdenke, lege ich die Hand ans Kinn.', 'Quando penso, metto la mano sotto il mento.'),
  (435, 1, 'Meu lábio está gelado.', 'My lip is cold.', 'Meine Lippe ist kalt.', 'Il mio labbro è freddo.'),
  (435, 2, 'Eu passo protetor no lábio antes de ir à praia.', 'I put balm on my lip before going to the beach.', 'Ich creme meine Lippe ein, bevor ich an den Strand gehe.', 'Metto il burrocacao sul labbro prima di andare in spiaggia.'),
  (28, 1, 'Eu vou para a cama.', 'I go to bed.', 'Ich gehe ins Bett.', 'Vado a letto.'),
  (28, 2, 'Depois da história, eu pulo na cama e durmo.', 'After the story, I jump into bed and sleep.', 'Nach der Geschichte hüpfe ich ins Bett und schlafe.', 'Dopo la storia, salto nel letto e dormo.'),
  (29, 1, 'A mesa é grande.', 'The table is big.', 'Der Tisch ist groß.', 'Il tavolo è grande.'),
  (29, 2, 'A família almoça junta na mesa da cozinha.', 'The family has lunch together at the kitchen table.', 'Die Familie isst zusammen am Küchentisch zu Mittag.', 'La famiglia pranza insieme al tavolo della cucina.'),
  (30, 1, 'Sente na cadeira.', 'Sit on the chair.', 'Setz dich auf den Stuhl.', 'Siediti sulla sedia.'),
  (30, 2, 'O gato dorme na cadeira perto da janela.', 'The cat sleeps on the chair by the window.', 'Die Katze schläft auf dem Stuhl am Fenster.', 'Il gatto dorme sulla sedia vicino alla finestra.'),
  (31, 1, 'Feche a porta.', 'Close the door.', 'Mach die Tür zu.', 'Chiudi la porta.'),
  (31, 2, 'Alguém está batendo na porta, vamos ver quem é.', 'Someone is knocking on the door, let''s see who it is.', 'Jemand klopft an die Tür, schauen wir, wer es ist.', 'Qualcuno bussa alla porta, andiamo a vedere chi è.'),
  (32, 1, 'Abra a janela.', 'Open the window.', 'Mach das Fenster auf.', 'Apri la finestra.'),
  (32, 2, 'Da janela do quarto eu vejo a lua.', 'From my bedroom window I can see the moon.', 'Aus dem Fenster in meinem Zimmer sehe ich den Mond.', 'Dalla finestra della mia camera vedo la luna.'),
  (33, 1, 'O copo tem água.', 'The glass has water.', 'Im Glas ist Wasser.', 'Nel bicchiere c''è acqua.'),
  (33, 2, 'Eu encho o copo de suco de laranja.', 'I fill the glass with orange juice.', 'Ich fülle das Glas mit Orangensaft.', 'Riempio il bicchiere di succo d''arancia.'),
  (34, 1, 'O prato está vazio.', 'The plate is empty.', 'Der Teller ist leer.', 'Il piatto è vuoto.'),
  (34, 2, 'Eu comi tudo e o prato ficou limpinho.', 'I ate everything and the plate is all clean.', 'Ich habe alles aufgegessen und der Teller ist ganz sauber.', 'Ho mangiato tutto e il piatto è pulitissimo.'),
  (35, 1, 'Eu como com a colher.', 'I eat with the spoon.', 'Ich esse mit dem Löffel.', 'Mangio con il cucchiaio.'),
  (35, 2, 'Eu tomo a sopa quente com uma colher grande.', 'I eat the hot soup with a big spoon.', 'Ich esse die heiße Suppe mit einem großen Löffel.', 'Mangio la zuppa calda con un cucchiaio grande.'),
  (36, 1, 'A panela está quente.', 'The pot is hot.', 'Der Topf ist heiß.', 'La pentola è calda.'),
  (36, 2, 'A vovó cozinha o arroz numa panela grande.', 'Grandma cooks the rice in a big pot.', 'Oma kocht den Reis in einem großen Topf.', 'La nonna cuoce il riso in una pentola grande.'),
  (37, 1, 'O sofá é macio.', 'The sofa is soft.', 'Das Sofa ist weich.', 'Il divano è morbido.'),
  (37, 2, 'A família assiste a um filme no sofá da sala.', 'The family watches a movie on the living room sofa.', 'Die Familie schaut auf dem Sofa im Wohnzimmer einen Film.', 'La famiglia guarda un film sul divano del soggiorno.'),
  (38, 1, 'O cobertor é quentinho.', 'The blanket is warm.', 'Die Decke ist warm.', 'La coperta è calda.'),
  (38, 2, 'No inverno, eu durmo com um cobertor bem grosso.', 'In winter, I sleep with a very thick blanket.', 'Im Winter schlafe ich mit einer ganz dicken Decke.', 'D''inverno dormo con una coperta molto pesante.'),
  (39, 1, 'O travesseiro é fofo.', 'The pillow is fluffy.', 'Das Kissen ist flauschig.', 'Il cuscino è soffice.'),
  (39, 2, 'Eu deito a cabeça no travesseiro e fecho os olhos.', 'I lay my head on the pillow and close my eyes.', 'Ich lege den Kopf aufs Kissen und mache die Augen zu.', 'Appoggio la testa sul cuscino e chiudo gli occhi.'),
  (40, 1, 'O relógio faz tique-taque.', 'The clock goes tick-tock.', 'Die Uhr macht tick-tack.', 'L''orologio fa tic-tac.'),
  (40, 2, 'O relógio da sala mostra que é hora de dormir.', 'The living room clock shows it''s time for bed.', 'Die Uhr im Wohnzimmer zeigt, dass es Zeit fürs Bett ist.', 'L''orologio del soggiorno dice che è ora di dormire.'),
  (41, 1, 'Onde está a chave?', 'Where is the key?', 'Wo ist der Schlüssel?', 'Dov''è la chiave?'),
  (41, 2, 'O papai abre a porta de casa com a chave.', 'Dad opens the front door with the key.', 'Papa schließt die Haustür mit dem Schlüssel auf.', 'Papà apre la porta di casa con la chiave.'),
  (42, 1, 'Eu me vejo no espelho.', 'I see myself in the mirror.', 'Ich sehe mich im Spiegel.', 'Mi vedo nello specchio.'),
  (42, 2, 'No espelho do banheiro, eu faço caretas engraçadas.', 'In the bathroom mirror, I make funny faces.', 'Im Badezimmerspiegel mache ich lustige Grimassen.', 'Nello specchio del bagno faccio delle smorfie buffe.'),
  (399, 1, 'Eu como com o garfo.', 'I eat with the fork.', 'Ich esse mit der Gabel.', 'Mangio con la forchetta.'),
  (399, 2, 'Eu pego o macarrão com o garfo e enrolo.', 'I pick up the pasta with the fork and twirl it.', 'Ich nehme die Nudeln mit der Gabel und drehe sie auf.', 'Prendo la pasta con la forchetta e la arrotolo.'),
  (400, 1, 'A faca corta.', 'The knife cuts.', 'Das Messer schneidet.', 'Il coltello taglia.'),
  (400, 2, 'O papai corta o pão com uma faca grande.', 'Dad cuts the bread with a big knife.', 'Papa schneidet das Brot mit einem großen Messer.', 'Papà taglia il pane con un coltello grande.'),
  (401, 1, 'A xícara é pequena.', 'The cup is small.', 'Die Tasse ist klein.', 'La tazza è piccola.'),
  (401, 2, 'A vovó toma chá numa xícara azul com flores.', 'Grandma drinks tea from a blue cup with flowers.', 'Oma trinkt Tee aus einer blauen Tasse mit Blumen.', 'La nonna beve il tè in una tazza blu con i fiori.'),
  (402, 1, 'A tigela está cheia.', 'The bowl is full.', 'Die Schüssel ist voll.', 'La ciotola è piena.'),
  (402, 2, 'De manhã, eu como cereal com leite numa tigela.', 'In the morning, I eat cereal with milk in a bowl.', 'Am Morgen esse ich Müsli mit Milch aus einer Schüssel.', 'La mattina mangio i cereali con il latte in una ciotola.'),
  (403, 1, 'A frigideira está quente.', 'The frying pan is hot.', 'Die Pfanne ist heiß.', 'La padella è calda.'),
  (403, 2, 'A mamãe frita um ovo na frigideira.', 'Mom fries an egg in the frying pan.', 'Mama brät ein Ei in der Pfanne.', 'La mamma frigge un uovo nella padella.'),
  (404, 1, 'A jarra tem suco.', 'The jug has juice.', 'Im Krug ist Saft.', 'Nella brocca c''è il succo.'),
  (404, 2, 'Eu sirvo água da jarra no copo de todo mundo.', 'I pour water from the jug into everyone''s glass.', 'Ich gieße allen Wasser aus dem Krug ins Glas.', 'Verso l''acqua dalla brocca nel bicchiere di tutti.'),
  (405, 1, 'A caneca é minha.', 'The mug is mine.', 'Der Becher gehört mir.', 'Il tazzone è mio.'),
  (405, 2, 'Eu tomo leite quente na minha caneca de urso.', 'I drink warm milk from my bear mug.', 'Ich trinke warme Milch aus meinem Bärenbecher.', 'Bevo il latte caldo nel mio tazzone con l''orso.'),
  (486, 1, 'O guarda-roupa é grande.', 'The wardrobe is big.', 'Der Kleiderschrank ist groß.', 'L''armadio è grande.'),
