  (56, 1, 'A ovelha faz mé.', 'The sheep goes baa.', 'Das Schaf macht mäh.', 'La pecora fa bee.'),
  (56, 2, 'A ovelha tem uma lã branca e macia.', 'The sheep has soft white wool.', 'Das Schaf hat weiche weiße Wolle.', 'La pecora ha la lana bianca e morbida.'),
  (57, 1, 'A abelha voa.', 'The bee flies.', 'Die Biene fliegt.', 'L''ape vola.'),
