  (95, 1, 'A chuva molha.', 'The rain makes things wet.', 'Der Regen macht nass.', 'La pioggia bagna.'),
  (95, 2, 'Quando cai chuva, eu uso galocha e guarda-chuva.', 'When the rain falls, I wear rain boots and use an umbrella.', 'Bei Regen ziehe ich Gummistiefel an und nehme einen Schirm.', 'Quando viene la pioggia, metto gli stivali e prendo l''ombrello.'),
  (97, 1, 'A montanha é alta.', 'The mountain is high.', 'Der Berg ist hoch.', 'La montagna è alta.'),
  (97, 2, 'No inverno, o topo da montanha fica branco de neve.', 'In winter, the top of the mountain is white with snow.', 'Im Winter ist die Spitze des Berges weiß vom Schnee.', 'D''inverno la cima della montagna è bianca di neve.'),
  (98, 1, 'O mar é azul.', 'The sea is blue.', 'Das Meer ist blau.', 'Il mare è blu.'),
  (98, 2, 'Eu pulo as ondas do mar com o papai.', 'I jump over the waves of the sea with Dad.', 'Ich springe mit Papa über die Wellen im Meer.', 'Salto le onde del mare con papà.'),
  (99, 1, 'O rio é comprido.', 'The river is long.', 'Der Fluss ist lang.', 'Il fiume è lungo.'),
  (99, 2, 'Os patos nadam no rio perto da ponte.', 'The ducks swim in the river near the bridge.', 'Die Enten schwimmen im Fluss an der Brücke.', 'Le anatre nuotano nel fiume vicino al ponte.'),
  (100, 1, 'O fogo é quente.', 'Fire is hot.', 'Das Feuer ist heiß.', 'Il fuoco è caldo.'),
  (100, 2, 'Não chegue perto do fogo, ele queima.', 'Don''t go near the fire, it burns.', 'Geh nicht zu nah ans Feuer, es ist heiß.', 'Non avvicinarti al fuoco, scotta.'),
  (101, 1, 'A neve é fria.', 'The snow is cold.', 'Der Schnee ist kalt.', 'La neve è fredda.'),
  (101, 2, 'Eu faço um boneco de neve com o vovô.', 'I make a snowman with Grandpa.', 'Ich baue mit Opa einen Schneemann.', 'Faccio un pupazzo di neve con il nonno.'),
