  (322, 1, 'O gelo é frio.', 'The ice is cold.', 'Das Eis ist kalt.', 'Il ghiaccio è freddo.'),
  (322, 2, 'Eu coloco gelo no suco para ficar geladinho.', 'I put ice in the juice to make it nice and cold.', 'Ich tue Eis in den Saft, damit er schön kalt ist.', 'Metto il ghiaccio nel succo per farlo bello freddo.'),
  (323, 1, 'O vento sopra.', 'The wind blows.', 'Der Wind weht.', 'Il vento soffia.'),
  (323, 2, 'O vento forte leva a minha pipa lá para cima.', 'The strong wind carries my kite way up high.', 'Der starke Wind trägt meinen Drachen hoch hinauf.', 'Il vento forte porta il mio aquilone in alto.'),
  (324, 1, 'O relâmpago brilha.', 'The lightning flashes.', 'Der Blitz leuchtet.', 'Il fulmine brilla.'),
  (324, 2, 'Depois do relâmpago, a gente escuta o trovão.', 'After the lightning, we hear the thunder.', 'Nach dem Blitz hören wir den Donner.', 'Dopo il fulmine sentiamo il tuono.'),
  (325, 1, 'A tempestade chegou.', 'The storm is here.', 'Der Sturm ist da.', 'È arrivata la tempesta.'),
  (325, 2, 'Durante a tempestade, a gente fica em casa lendo.', 'During the storm, we stay home and read.', 'Während des Sturms bleiben wir zu Hause und lesen.', 'Durante la tempesta restiamo a casa a leggere.'),
  (326, 1, 'O dia está nublado.', 'The day is cloudy.', 'Der Tag ist bewölkt.', 'La giornata è nuvolosa.'),
  (326, 2, 'Hoje o céu está nublado e talvez chova.', 'Today the sky is cloudy and it might rain.', 'Heute ist der Himmel bewölkt und vielleicht regnet es.', 'Oggi il cielo è nuvoloso e forse piove.'),
  (327, 1, 'A sopa está quente.', 'The soup is hot.', 'Die Suppe ist heiß.', 'La zuppa è calda.'),
  (327, 2, 'Cuidado, o chá está quente, espere esfriar.', 'Careful, the tea is hot, wait for it to cool.', 'Vorsicht, der Tee ist heiß, warte, bis er abkühlt.', 'Attenzione, il tè è caldo, aspetta che si raffreddi.'),
  (328, 1, 'O sorvete está frio.', 'The ice cream is cold.', 'Das Eis ist kalt.', 'Il gelato è freddo.'),
  (328, 2, 'Hoje está frio, então eu uso luva e cachecol.', 'It''s cold today, so I wear gloves and a scarf.', 'Heute ist es kalt, also trage ich Handschuhe und einen Schal.', 'Oggi fa freddo, quindi porto i guanti e la sciarpa.'),
  (329, 1, 'O céu é azul.', 'The sky is blue.', 'Der Himmel ist blau.', 'Il cielo è azzurro.'),
  (329, 2, 'Eu vejo um avião voando alto no céu.', 'I see a plane flying high in the sky.', 'Ich sehe ein Flugzeug hoch am Himmel fliegen.', 'Vedo un aereo che vola alto nel cielo.'),
  (414, 1, 'A Terra é um planeta.', 'Earth is a planet.', 'Die Erde ist ein Planet.', 'La Terra è un pianeta.'),
  (414, 2, 'O planeta onde a gente mora se chama Terra.', 'The planet where we live is called Earth.', 'Der Planet, auf dem wir wohnen, heißt Erde.', 'Il pianeta dove viviamo si chiama Terra.'),
  (415, 1, 'Saturno tem anéis.', 'Saturn has rings.', 'Der Saturn hat Ringe.', 'Saturno ha gli anelli.'),
  (415, 2, 'Saturno é um planeta grande com anéis em volta.', 'Saturn is a big planet with rings around it.', 'Der Saturn ist ein großer Planet mit Ringen drumherum.', 'Saturno è un pianeta grande con gli anelli intorno.'),
  (416, 1, 'O cometa tem cauda.', 'The comet has a tail.', 'Der Komet hat einen Schweif.', 'La cometa ha la coda.'),
  (416, 2, 'O cometa passa no céu com uma cauda brilhante.', 'The comet crosses the sky with a shiny tail.', 'Der Komet fliegt mit einem leuchtenden Schweif über den Himmel.', 'La cometa attraversa il cielo con una coda luminosa.'),
  (417, 1, 'Olha, uma estrela cadente!', 'Look, a shooting star!', 'Schau, eine Sternschnuppe!', 'Guarda, una stella cadente!'),
  (417, 2, 'Quando vejo uma estrela cadente, eu faço um pedido.', 'When I see a shooting star, I make a wish.', 'Wenn ich eine Sternschnuppe sehe, wünsche ich mir etwas.', 'Quando vedo una stella cadente, esprimo un desiderio.'),
  (418, 1, 'O astronauta voa.', 'The astronaut flies.', 'Der Astronaut fliegt.', 'L''astronauta vola.'),
  (418, 2, 'O astronauta viaja de foguete até a lua.', 'The astronaut travels by rocket to the moon.', 'Der Astronaut fliegt mit der Rakete zum Mond.', 'L''astronauta va sulla luna con il razzo.'),
  (419, 1, 'O disco voador gira.', 'The flying saucer spins.', 'Das Ufo dreht sich.', 'Il disco volante gira.'),
  (419, 2, 'No desenho, um disco voador pousa no jardim.', 'In the cartoon, a flying saucer lands in the garden.', 'Im Zeichentrickfilm landet ein Ufo im Garten.', 'Nel cartone animato un disco volante atterra in giardino.'),
  (420, 1, 'O satélite gira.', 'The satellite goes around.', 'Der Satellit kreist.', 'Il satellite gira.'),
  (420, 2, 'O satélite gira em volta da Terra lá no espaço.', 'The satellite circles the Earth up in space.', 'Der Satellit kreist oben im Weltall um die Erde.', 'Il satellite gira intorno alla Terra nello spazio.'),
  (444, 1, 'A primavera tem flores.', 'Spring has flowers.', 'Im Frühling gibt es Blumen.', 'La primavera ha i fiori.'),
  (444, 2, 'Na primavera, o jardim fica cheio de flores coloridas.', 'In spring, the garden is full of colorful flowers.', 'Im Frühling ist der Garten voller bunter Blumen.', 'In primavera il giardino è pieno di fiori colorati.'),
  (445, 1, 'O verão é quente.', 'Summer is hot.', 'Der Sommer ist heiß.', 'L''estate è calda.'),
  (445, 2, 'No verão, a gente vai à praia e toma sorvete.', 'In summer, we go to the beach and eat ice cream.', 'Im Sommer gehen wir an den Strand und essen Eis.', 'D''estate andiamo al mare e mangiamo il gelato.'),
  (446, 1, 'O outono tem folhas.', 'Autumn has leaves.', 'Im Herbst gibt es Blätter.', 'L''autunno ha le foglie.'),
  (446, 2, 'No outono, as folhas caem e cobrem o chão.', 'In autumn, the leaves fall and cover the ground.', 'Im Herbst fallen die Blätter und bedecken den Boden.', 'In autunno le foglie cadono e coprono il terreno.'),
  (447, 1, 'O inverno é frio.', 'Winter is cold.', 'Der Winter ist kalt.', 'L''inverno è freddo.'),
  (447, 2, 'No inverno, eu tomo chocolate quente debaixo do cobertor.', 'In winter, I drink hot chocolate under the blanket.', 'Im Winter trinke ich heiße Schokolade unter der Decke.', 'D''inverno bevo la cioccolata calda sotto la coperta.'),
  (96, 1, 'Eu bebo água.', 'I drink water.', 'Ich trinke Wasser.', 'Bevo l''acqua.'),
  (96, 2, 'Depois de correr, eu bebo um copo de água gelada.', 'After running, I drink a glass of cold water.', 'Nach dem Rennen trinke ich ein Glas kaltes Wasser.', 'Dopo aver corso bevo un bicchiere d''acqua fresca.'),
  (103, 1, 'A maçã é vermelha.', 'The apple is red.', 'Der Apfel ist rot.', 'La mela è rossa.'),
  (103, 2, 'Eu levo uma maçã no lanche da escola.', 'I take an apple for my school snack.', 'Ich nehme einen Apfel als Pausensnack mit in die Schule.', 'Porto una mela per la merenda a scuola.'),
  (104, 1, 'A uva é doce.', 'The grape is sweet.', 'Die Traube ist süß.', 'L''uva è dolce.'),
  (104, 2, 'O vovô pega uva roxa no pé para mim.', 'Grandpa picks purple grapes from the vine for me.', 'Opa pflückt für mich lila Trauben vom Weinstock.', 'Il nonno raccoglie l''uva nera dalla vite per me.'),
  (105, 1, 'A laranja é redonda.', 'The orange is round.', 'Die Orange ist rund.', 'L''arancia è rotonda.'),
  (105, 2, 'A mamãe faz suco com três laranjas bem doces.', 'Mom makes juice with three very sweet oranges.', 'Mama macht Saft aus drei sehr süßen Orangen.', 'La mamma fa il succo con tre arance molto dolci.'),
  (106, 1, 'Eu como pão.', 'I eat bread.', 'Ich esse Brot.', 'Mangio il pane.'),
  (106, 2, 'De manhã, eu como pão com manteiga e leite.', 'In the morning, I eat bread with butter and milk.', 'Morgens esse ich Brot mit Butter und trinke Milch.', 'La mattina mangio il pane con il burro e bevo il latte.'),
  (107, 1, 'Eu bebo leite.', 'I drink milk.', 'Ich trinke Milch.', 'Bevo il latte.'),
  (107, 2, 'Antes de dormir, eu tomo um copo de leite morno.', 'Before bed, I drink a glass of warm milk.', 'Vor dem Schlafen trinke ich ein Glas warme Milch.', 'Prima di dormire bevo un bicchiere di latte tiepido.'),
  (108, 1, 'A banana é amarela.', 'The banana is yellow.', 'Die Banane ist gelb.', 'La banana è gialla.'),
  (108, 2, 'O macaco descasca a banana e come tudinho.', 'The monkey peels the banana and eats it all up.', 'Der Affe schält die Banane und isst sie ganz auf.', 'La scimmia sbuccia la banana e la mangia tutta.'),
  (109, 1, 'Eu como um ovo.', 'I eat an egg.', 'Ich esse ein Ei.', 'Mangio un uovo.'),
  (109, 2, 'No café da manhã, a vovó faz ovo mexido.', 'For breakfast, Grandma makes scrambled eggs.', 'Zum Frühstück macht Oma Rührei.', 'A colazione la nonna fa le uova strapazzate.'),
  (110, 1, 'O rato gosta de queijo.', 'The mouse likes cheese.', 'Die Maus mag Käse.', 'Al topo piace il formaggio.'),
  (110, 2, 'Eu como um sanduíche de queijo no lanche.', 'I eat a cheese sandwich for my snack.', 'Zur Pause esse ich ein Käsebrot.', 'Per merenda mangio un panino al formaggio.'),
  (111, 1, 'O bolo é gostoso.', 'The cake is yummy.', 'Der Kuchen ist lecker.', 'La torta è buona.'),
  (111, 2, 'No meu aniversário tem bolo com velas.', 'On my birthday there is cake with candles.', 'An meinem Geburtstag gibt es Kuchen mit Kerzen.', 'Al mio compleanno c''è la torta con le candeline.'),
  (112, 1, 'Eu como arroz.', 'I eat rice.', 'Ich esse Reis.', 'Mangio il riso.'),
  (112, 2, 'No almoço, eu como arroz, feijão e salada.', 'For lunch, I eat rice, beans, and salad.', 'Zum Mittagessen esse ich Reis, Bohnen und Salat.', 'A pranzo mangio riso, fagioli e insalata.'),
  (113, 1, 'Eu tomo suco.', 'I drink juice.', 'Ich trinke Saft.', 'Bevo il succo.'),
  (113, 2, 'Eu gosto de suco de uva com bastante gelo.', 'I like grape juice with lots of ice.', 'Ich mag Traubensaft mit viel Eis.', 'Mi piace il succo d''uva con tanto ghiaccio.'),
  (114, 1, 'O biscoito é crocante.', 'The cookie is crunchy.', 'Der Keks ist knusprig.', 'Il biscotto è croccante.'),
  (114, 2, 'A vovó assa biscoitos de chocolate para o lanche.', 'Grandma bakes chocolate cookies for snack time.', 'Oma backt Schokoladenkekse für die Pause.', 'La nonna cuoce i biscotti al cioccolato per la merenda.'),
  (115, 1, 'O sorvete é gelado.', 'The ice cream is cold.', 'Das Eis ist kalt.', 'Il gelato è freddo.'),
  (115, 2, 'No verão, eu tomo sorvete de morango na praia.', 'In summer, I eat strawberry ice cream at the beach.', 'Im Sommer esse ich am Strand Erdbeereis.', 'D''estate mangio il gelato alla fragola in spiaggia.'),
  (116, 1, 'O coelho come cenoura.', 'The rabbit eats a carrot.', 'Der Hase frisst eine Karotte.', 'Il coniglio mangia una carota.'),
  (116, 2, 'A cenoura laranja cresce debaixo da terra.', 'The orange carrot grows under the ground.', 'Die orangefarbene Karotte wächst unter der Erde.', 'La carota arancione cresce sotto terra.'),
  (117, 1, 'O tomate é vermelho.', 'The tomato is red.', 'Die Tomate ist rot.', 'Il pomodoro è rosso.'),
  (117, 2, 'O papai corta o tomate para a salada.', 'Dad cuts the tomato for the salad.', 'Papa schneidet die Tomate für den Salat.', 'Papà taglia il pomodoro per l''insalata.'),
  (118, 1, 'O pirulito é doce.', 'The lollipop is sweet.', 'Der Lutscher ist süß.', 'Il lecca-lecca è dolce.'),
  (118, 2, 'Eu ganhei um pirulito colorido na festa.', 'I got a colorful lollipop at the party.', 'Ich habe auf der Party einen bunten Lutscher bekommen.', 'Alla festa ho ricevuto un lecca-lecca colorato.'),
  (119, 1, 'Eu como macarrão.', 'I eat pasta.', 'Ich esse Nudeln.', 'Mangio la pasta.'),
  (119, 2, 'A vovó faz macarrão com molho de tomate.', 'Grandma makes pasta with tomato sauce.', 'Oma macht Nudeln mit Tomatensoße.', 'La nonna fa la pasta al sugo di pomodoro.'),
  (120, 1, 'O chá está quente.', 'The tea is hot.', 'Der Tee ist heiß.', 'Il tè è caldo.'),
  (120, 2, 'Quando eu fico doente, a mamãe faz um chá com mel.', 'When I''m sick, Mom makes tea with honey.', 'Wenn ich krank bin, macht Mama Tee mit Honig.', 'Quando sto male, la mamma fa il tè con il miele.'),
  (121, 1, 'O papai toma café.', 'Dad drinks coffee.', 'Papa trinkt Kaffee.', 'Papà beve il caffè.'),
  (121, 2, 'De manhã, o papai toma café numa caneca grande.', 'In the morning, Dad drinks coffee from a big mug.', 'Morgens trinkt Papa Kaffee aus einem großen Becher.', 'La mattina papà beve il caffè in un tazzone grande.'),
  (292, 1, 'O morango é vermelho.', 'The strawberry is red.', 'Die Erdbeere ist rot.', 'La fragola è rossa.'),
  (292, 2, 'Eu coloco morango no iogurte do café da manhã.', 'I put strawberries in my breakfast yogurt.', 'Ich tue Erdbeeren in meinen Joghurt zum Frühstück.', 'Metto le fragole nello yogurt della colazione.'),
  (293, 1, 'A melancia é grande.', 'The watermelon is big.', 'Die Wassermelone ist groß.', 'L''anguria è grande.'),
  (293, 2, 'No verão, a gente come melancia gelada no quintal.', 'In summer, we eat cold watermelon in the yard.', 'Im Sommer essen wir im Garten kalte Wassermelone.', 'D''estate mangiamo l''anguria fresca in cortile.'),
  (294, 1, 'O abacaxi é doce.', 'The pineapple is sweet.', 'Die Ananas ist süß.', 'L''ananas è dolce.'),
  (294, 2, 'O abacaxi tem uma coroa verde em cima.', 'The pineapple has a green crown on top.', 'Die Ananas hat oben eine grüne Krone.', 'L''ananas ha una corona verde in cima.'),
  (295, 1, 'A pera é verde.', 'The pear is green.', 'Die Birne ist grün.', 'La pera è verde.'),
  (295, 2, 'Eu como uma pera madura e suculenta.', 'I eat a ripe, juicy pear.', 'Ich esse eine reife, saftige Birne.', 'Mangio una pera matura e succosa.'),
  (296, 1, 'O limão é azedo.', 'The lemon is sour.', 'Die Zitrone ist sauer.', 'Il limone è aspro.'),
  (296, 2, 'A vovó espreme o limão para fazer limonada.', 'Grandma squeezes the lemon to make lemonade.', 'Oma presst die Zitrone für die Limonade aus.', 'La nonna spreme il limone per fare la limonata.'),
  (297, 1, 'O abacate é verde.', 'The avocado is green.', 'Die Avocado ist grün.', 'L''avocado è verde.'),
  (297, 2, 'O abacate tem um caroço grande no meio.', 'The avocado has a big pit in the middle.', 'Die Avocado hat in der Mitte einen großen Kern.', 'L''avocado ha un nocciolo grande in mezzo.'),
  (298, 1, 'A cereja é pequena.', 'The cherry is small.', 'Die Kirsche ist klein.', 'La ciliegia è piccola.'),
  (298, 2, 'Tem uma cereja vermelha em cima do bolo.', 'There is a red cherry on top of the cake.', 'Oben auf dem Kuchen liegt eine rote Kirsche.', 'C''è una ciliegia rossa sopra la torta.'),
  (299, 1, 'O coco é duro.', 'The coconut is hard.', 'Die Kokosnuss ist hart.', 'Il cocco è duro.'),
  (299, 2, 'O coco cai do coqueiro lá na praia.', 'The coconut falls from the palm tree at the beach.', 'Am Strand fällt die Kokosnuss von der Palme.', 'Il cocco cade dalla palma in spiaggia.'),
  (300, 1, 'A alface é verde.', 'The lettuce is green.', 'Der Salat ist grün.', 'La lattuga è verde.'),
  (300, 2, 'A mamãe lava a alface antes de fazer a salada.', 'Mom washes the lettuce before making the salad.', 'Mama wäscht den Salat, bevor sie ihn anmacht.', 'La mamma lava la lattuga prima di fare l''insalata.'),
  (301, 1, 'A batata é marrom.', 'The potato is brown.', 'Die Kartoffel ist braun.', 'La patata è marrone.'),
  (301, 2, 'O papai faz purê de batata para o jantar.', 'Dad makes mashed potatoes for dinner.', 'Papa macht Kartoffelbrei zum Abendessen.', 'Papà fa il purè di patate per cena.'),
  (302, 1, 'O milho é amarelo.', 'The corn is yellow.', 'Der Mais ist gelb.', 'Il mais è giallo.'),
  (302, 2, 'Na festa junina, a gente come milho cozido.', 'At the June festival, we eat boiled corn.', 'Beim Sommerfest essen wir gekochten Mais.', 'Alla festa d''estate mangiamo il mais bollito.'),
  (303, 1, 'A cebola faz chorar.', 'The onion makes you cry.', 'Die Zwiebel bringt einen zum Weinen.', 'La cipolla fa piangere.'),
  (303, 2, 'Quando a mamãe corta cebola, os olhos dela choram.', 'When Mom cuts an onion, her eyes water.', 'Wenn Mama Zwiebeln schneidet, tränen ihre Augen.', 'Quando la mamma taglia la cipolla, le lacrimano gli occhi.'),
  (304, 1, 'O brócolis é verde.', 'Broccoli is green.', 'Der Brokkoli ist grün.', 'I broccoli sono verdi.'),
  (304, 2, 'O brócolis parece uma arvorezinha no meu prato.', 'The broccoli looks like a little tree on my plate.', 'Der Brokkoli sieht auf meinem Teller aus wie ein kleiner Baum.', 'I broccoli sembrano piccoli alberi nel mio piatto.'),
  (305, 1, 'A abóbora é laranja.', 'The pumpkin is orange.', 'Der Kürbis ist orange.', 'La zucca è arancione.'),
  (305, 2, 'A vovó faz sopa de abóbora quando está frio.', 'Grandma makes pumpkin soup when it''s cold.', 'Wenn es kalt ist, kocht Oma Kürbissuppe.', 'Quando fa freddo, la nonna fa la zuppa di zucca.'),
  (306, 1, 'O melão é doce.', 'The melon is sweet.', 'Die Melone ist süß.', 'Il melone è dolce.'),
  (306, 2, 'O melão amarelo é gostoso e cheio de suco.', 'The yellow melon is tasty and full of juice.', 'Die gelbe Melone ist lecker und sehr saftig.', 'Il melone giallo è buono e pieno di succo.'),
  (378, 1, 'O refrigerante tem bolhas.', 'Soda has bubbles.', 'Im Softdrink sind Bläschen.', 'La bibita ha le bollicine.'),
  (378, 2, 'Na festa, eu tomo só um pouquinho de refrigerante.', 'At the party, I drink just a little soda.', 'Auf der Party trinke ich nur ein bisschen Softdrink.', 'Alla festa bevo solo un po'' di bibita.'),
  (379, 1, 'A limonada é gelada.', 'The lemonade is cold.', 'Die Limonade ist kalt.', 'La limonata è fresca.'),
  (379, 2, 'Num dia quente, uma limonada gelada é muito boa.', 'On a hot day, a cold lemonade is really good.', 'An einem heißen Tag ist eine kalte Limonade richtig gut.', 'In una giornata calda, una limonata fresca è buonissima.'),
  (380, 1, 'A vitamina é de banana.', 'The smoothie is made of banana.', 'Der Smoothie ist aus Banane.', 'Il frullato è alla banana.'),
  (380, 2, 'A mamãe bate banana com leite e faz uma vitamina.', 'Mom blends banana with milk to make a smoothie.', 'Mama mixt Banane mit Milch und macht einen Smoothie.', 'La mamma frulla la banana con il latte e fa un frullato.'),
  (381, 1, 'A água de coco é gostosa.', 'Coconut water is tasty.', 'Kokoswasser ist lecker.', 'L''acqua di cocco è buona.'),
  (381, 2, 'Na praia, eu tomo água de coco de canudinho.', 'At the beach, I drink coconut water with a straw.', 'Am Strand trinke ich Kokoswasser mit einem Strohhalm.', 'In spiaggia bevo l''acqua di cocco con la cannuccia.'),
  (382, 1, 'Eu tomo achocolatado.', 'I drink chocolate milk.', 'Ich trinke Kakao.', 'Bevo il latte al cioccolato.'),
  (382, 2, 'De manhã, eu tomo achocolatado com biscoito.', 'In the morning, I have chocolate milk with a cookie.', 'Morgens trinke ich Kakao und esse einen Keks.', 'La mattina bevo il latte al cioccolato con un biscotto.'),
  (516, 1, 'A pizza está quente.', 'The pizza is hot.', 'Die Pizza ist heiß.', 'La pizza è calda.'),
  (516, 2, 'No sábado, a família come pizza de queijo.', 'On Saturday, the family eats cheese pizza.', 'Am Samstag isst die Familie Käsepizza.', 'Il sabato la famiglia mangia la pizza al formaggio.'),
  (517, 1, 'O hambúrguer é grande.', 'The hamburger is big.', 'Der Hamburger ist groß.', 'L''hamburger è grande.'),
  (517, 2, 'O papai faz hambúrguer com alface e tomate.', 'Dad makes a hamburger with lettuce and tomato.', 'Papa macht einen Hamburger mit Salat und Tomate.', 'Papà fa l''hamburger con lattuga e pomodoro.'),
  (518, 1, 'A sopa está quente.', 'The soup is hot.', 'Die Suppe ist heiß.', 'La zuppa è calda.'),
  (518, 2, 'Eu sopro a sopa antes de colocar na boca.', 'I blow on the soup before I put it in my mouth.', 'Ich puste auf die Suppe, bevor ich sie in den Mund nehme.', 'Soffio sulla zuppa prima di metterla in bocca.'),
  (519, 1, 'A salada é verde.', 'The salad is green.', 'Der Salat ist grün.', 'L''insalata è verde.'),
  (519, 2, 'A salada tem alface, tomate e cenoura.', 'The salad has lettuce, tomato, and carrot.', 'Im Salat sind Blattsalat, Tomate und Karotte.', 'L''insalata ha lattuga, pomodoro e carota.'),
  (520, 1, 'O iogurte é cremoso.', 'The yogurt is creamy.', 'Der Joghurt ist cremig.', 'Lo yogurt è cremoso.'),
  (520, 2, 'Eu como iogurte de morango com a colher pequena.', 'I eat strawberry yogurt with the little spoon.', 'Ich esse Erdbeerjoghurt mit dem kleinen Löffel.', 'Mangio lo yogurt alla fragola con il cucchiaino.'),
  (521, 1, 'A manteiga é amarela.', 'The butter is yellow.', 'Die Butter ist gelb.', 'Il burro è giallo.'),
  (521, 2, 'Eu passo manteiga no pão quentinho.', 'I spread butter on the warm bread.', 'Ich streiche Butter auf das warme Brot.', 'Spalmo il burro sul pane caldo.'),
  (522, 1, 'O mel é doce.', 'Honey is sweet.', 'Der Honig ist süß.', 'Il miele è dolce.'),
  (522, 2, 'As abelhas fazem o mel que eu ponho no chá.', 'The bees make the honey I put in my tea.', 'Die Bienen machen den Honig, den ich in meinen Tee tue.', 'Le api fanno il miele che metto nel tè.'),
  (523, 1, 'O chocolate é gostoso.', 'Chocolate is yummy.', 'Schokolade ist lecker.', 'Il cioccolato è buono.'),
  (523, 2, 'O chocolate derreteu na minha mão no sol.', 'The chocolate melted in my hand in the sun.', 'Die Schokolade ist in der Sonne in meiner Hand geschmolzen.', 'Il cioccolato si è sciolto nella mia mano al sole.'),
  (524, 1, 'A pipoca estoura.', 'The popcorn pops.', 'Das Popcorn ploppt.', 'Il popcorn scoppietta.'),
  (524, 2, 'A gente come pipoca enquanto assiste ao filme.', 'We eat popcorn while we watch the movie.', 'Wir essen Popcorn, während wir den Film schauen.', 'Mangiamo il popcorn mentre guardiamo il film.'),
  (525, 1, 'A batata frita é crocante.', 'The fries are crunchy.', 'Die Pommes sind knusprig.', 'Le patatine fritte sono croccanti.'),
  (525, 2, 'Eu como hambúrguer com batata frita no sábado.', 'I eat a hamburger with fries on Saturday.', 'Am Samstag esse ich einen Hamburger mit Pommes.', 'Il sabato mangio l''hamburger con le patatine fritte.'),
  (527, 1, 'O sanduíche é grande.', 'The sandwich is big.', 'Das Sandwich ist groß.', 'Il panino è grande.'),
  (527, 2, 'Eu levo um sanduíche de queijo para o piquenique.', 'I take a cheese sandwich to the picnic.', 'Ich nehme ein Käsesandwich zum Picknick mit.', 'Porto un panino al formaggio al picnic.'),
  (528, 1, 'A panqueca é redonda.', 'The pancake is round.', 'Der Pfannkuchen ist rund.', 'La frittella è rotonda.'),
  (528, 2, 'O papai joga a panqueca para cima e pega na frigideira.', 'Dad flips the pancake up and catches it in the pan.', 'Papa wirft den Pfannkuchen hoch und fängt ihn mit der Pfanne.', 'Papà lancia la frittella in aria e la riprende con la padella.'),
  (122, 1, 'Eu chuto a bola.', 'I kick the ball.', 'Ich schieße den Ball.', 'Calcio la palla.'),
  (122, 2, 'O cachorro corre atrás da bola vermelha no parque.', 'The dog runs after the red ball in the park.', 'Der Hund rennt im Park dem roten Ball hinterher.', 'Il cane corre dietro alla palla rossa nel parco.'),
  (123, 1, 'A boneca dorme.', 'The doll is sleeping.', 'Die Puppe schläft.', 'La bambola dorme.'),
  (123, 2, 'Eu coloco a boneca no carrinho e passeio com ela.', 'I put the doll in the stroller and take her for a walk.', 'Ich lege die Puppe in den Puppenwagen und fahre mit ihr spazieren.', 'Metto la bambola nel passeggino e la porto a spasso.'),
  (124, 1, 'A pipa voa.', 'The kite flies.', 'Der Drachen fliegt.', 'L''aquilone vola.'),
  (124, 2, 'Com o vento forte, a pipa sobe bem alto.', 'With the strong wind, the kite goes up very high.', 'Bei starkem Wind steigt der Drachen ganz hoch.', 'Con il vento forte, l''aquilone sale molto in alto.'),
  (125, 1, 'Jogue o dado.', 'Roll the dice.', 'Wirf den Würfel.', 'Tira il dado.'),
  (125, 2, 'Eu jogo o dado e ando seis casas no jogo.', 'I roll the dice and move six spaces in the game.', 'Ich würfle und gehe im Spiel sechs Felder vor.', 'Tiro il dado e vado avanti di sei caselle nel gioco.'),
  (126, 1, 'O ioiô sobe e desce.', 'The yo-yo goes up and down.', 'Das Jo-Jo geht hoch und runter.', 'Lo yo-yo va su e giù.'),
  (126, 2, 'O vovô me ensina a brincar com o ioiô.', 'Grandpa teaches me how to play with the yo-yo.', 'Opa zeigt mir, wie man mit dem Jo-Jo spielt.', 'Il nonno mi insegna a giocare con lo yo-yo.'),
  (127, 1, 'O carrinho é rápido.', 'The toy car is fast.', 'Das Auto ist schnell.', 'La macchinina è veloce.'),
  (127, 2, 'Eu empurro o carrinho azul pelo tapete da sala.', 'I push the blue toy car across the living room rug.', 'Ich schiebe das blaue Auto über den Teppich im Wohnzimmer.', 'Spingo la macchinina blu sul tappeto del soggiorno.'),
  (128, 1, 'O ursinho é fofo.', 'The teddy bear is cuddly.', 'Der Teddybär ist kuschelig.', 'L''orsacchiotto è morbido.'),
  (128, 2, 'Eu durmo abraçando o meu ursinho marrom.', 'I sleep hugging my brown teddy bear.', 'Ich schlafe mit meinem braunen Teddybär im Arm.', 'Dormo abbracciando il mio orsacchiotto marrone.'),
  (129, 1, 'O balão é vermelho.', 'The balloon is red.', 'Der Luftballon ist rot.', 'Il palloncino è rosso.'),
  (129, 2, 'O balão escapou da minha mão e voou para o céu.', 'The balloon slipped out of my hand and flew into the sky.', 'Der Luftballon ist mir aus der Hand gerutscht und in den Himmel geflogen.', 'Il palloncino mi è scappato di mano ed è volato in cielo.'),
  (130, 1, 'O pião gira.', 'The spinning top spins.', 'Der Kreisel dreht sich.', 'La trottola gira.'),
  (130, 2, 'O pião colorido gira, gira e depois cai.', 'The colorful spinning top spins and spins and then falls over.', 'Der bunte Kreisel dreht sich und dreht sich und fällt dann um.', 'La trottola colorata gira, gira e poi cade.'),
  (131, 1, 'Eu empilho os blocos.', 'I stack the blocks.', 'Ich staple die Bauklötze.', 'Impilo i cubi.'),
  (131, 2, 'Com os blocos, eu construo uma torre bem alta.', 'With the blocks, I build a very tall tower.', 'Mit den Bauklötzen baue ich einen ganz hohen Turm.', 'Con i cubi costruisco una torre altissima.'),
  (132, 1, 'O robô anda.', 'The robot walks.', 'Der Roboter läuft.', 'Il robot cammina.'),
  (132, 2, 'O meu robô acende as luzes e fala comigo.', 'My robot turns on its lights and talks to me.', 'Mein Roboter macht seine Lichter an und spricht mit mir.', 'Il mio robot accende le luci e parla con me.'),
  (133, 1, 'O trenzinho faz piuí.', 'The train goes choo-choo.', 'Der Zug macht tut-tut.', 'Il trenino fa ciuf ciuf.'),
  (133, 2, 'O trenzinho passa pelo túnel e chega na estação.', 'The toy train goes through the tunnel and reaches the station.', 'Der Zug fährt durch den Tunnel und kommt am Bahnhof an.', 'Il trenino passa nella galleria e arriva alla stazione.'),
  (134, 1, 'O baldinho tem areia.', 'The bucket has sand in it.', 'Im Eimer ist Sand.', 'Nel secchiello c''è la sabbia.'),
  (134, 2, 'Na praia, eu encho o baldinho de areia e faço um castelo.', 'At the beach, I fill the bucket with sand and make a castle.', 'Am Strand fülle ich den Eimer mit Sand und baue eine Burg.', 'In spiaggia riempio il secchiello di sabbia e faccio un castello.'),
  (135, 1, 'Eu ando de bicicleta.', 'I ride my bicycle.', 'Ich fahre Fahrrad.', 'Vado in bicicletta.'),
  (135, 2, 'O papai me ensina a andar de bicicleta sem rodinha.', 'Dad teaches me to ride my bicycle without training wheels.', 'Papa bringt mir bei, ohne Stützräder Fahrrad zu fahren.', 'Papà mi insegna ad andare in bicicletta senza rotelle.'),
  (136, 1, 'O quebra-cabeça tem peças.', 'The puzzle has pieces.', 'Das Puzzle hat Teile.', 'Il puzzle ha i pezzi.'),
  (136, 2, 'A família monta um quebra-cabeça de cem peças.', 'The family puts together a puzzle with a hundred pieces.', 'Die Familie legt ein Puzzle mit hundert Teilen.', 'La famiglia fa un puzzle da cento pezzi.'),
  (137, 1, 'A maçã é vermelha.', 'The apple is red.', 'Der Apfel ist rot.', 'La mela è rossa.'),
  (137, 2, 'O bombeiro dirige um caminhão vermelho e grande.', 'The firefighter drives a big red truck.', 'Der Feuerwehrmann fährt ein großes rotes Feuerwehrauto.', 'Il pompiere guida un grande camion rosso.'),
  (138, 1, 'O céu é azul.', 'The sky is blue.', 'Der Himmel ist blau.', 'Il cielo è blu.'),
  (138, 2, 'O peixe nada no mar azul e transparente.', 'The fish swims in the clear blue sea.', 'Der Fisch schwimmt im klaren blauen Meer.', 'Il pesce nuota nel mare blu e trasparente.'),
  (139, 1, 'O sol é amarelo.', 'The sun is yellow.', 'Die Sonne ist gelb.', 'Il sole è giallo.'),
  (139, 2, 'O pintinho amarelo segue a galinha pelo quintal.', 'The yellow chick follows the hen around the yard.', 'Das gelbe Küken läuft dem Huhn durch den Hof hinterher.', 'Il pulcino giallo segue la gallina nel cortile.'),
  (140, 1, 'A folha é verde.', 'The leaf is green.', 'Das Blatt ist grün.', 'La foglia è verde.'),
  (140, 2, 'O sapo verde pula de uma folha para outra.', 'The green frog jumps from one leaf to another.', 'Der grüne Frosch springt von einem Blatt zum nächsten.', 'La rana verde salta da una foglia all''altra.'),
  (141, 1, 'A abóbora é laranja.', 'The pumpkin is orange.', 'Der Kürbis ist orange.', 'La zucca è arancione.'),
  (141, 2, 'O céu fica laranja quando o sol vai embora.', 'The sky turns orange when the sun goes down.', 'Der Himmel wird orange, wenn die Sonne untergeht.', 'Il cielo diventa arancione quando tramonta il sole.'),
  (142, 1, 'O porco é rosa.', 'The pig is pink.', 'Das Schwein ist rosa.', 'Il maiale è rosa.'),
  (142, 2, 'A bailarina usa uma saia rosa e sapatilhas.', 'The dancer wears a pink skirt and ballet shoes.', 'Die Ballerina trägt einen rosa Rock und Ballettschuhe.', 'La ballerina porta una gonna rosa e le scarpette.'),
  (143, 1, 'A uva é roxa.', 'The grape is purple.', 'Die Traube ist lila.', 'L''uva è viola.'),
  (143, 2, 'Eu pinto um dinossauro roxo com bolinhas verdes.', 'I paint a purple dinosaur with green dots.', 'Ich male einen lila Dinosaurier mit grünen Punkten.', 'Dipingo un dinosauro viola a pois verdi.'),
  (144, 1, 'O gato é preto.', 'The cat is black.', 'Die Katze ist schwarz.', 'Il gatto è nero.'),
  (144, 2, 'De noite, o céu fica preto e cheio de estrelas.', 'At night, the sky turns black and full of stars.', 'In der Nacht wird der Himmel schwarz und voller Sterne.', 'Di notte il cielo diventa nero e pieno di stelle.'),
  (145, 1, 'A neve é branca.', 'The snow is white.', 'Der Schnee ist weiß.', 'La neve è bianca.'),
  (145, 2, 'A ovelha branca come grama no campo verde.', 'The white sheep eats grass in the green field.', 'Das weiße Schaf frisst Gras auf der grünen Wiese.', 'La pecora bianca mangia l''erba nel prato verde.'),
  (146, 1, 'O elefante é cinza.', 'The elephant is gray.', 'Der Elefant ist grau.', 'L''elefante è grigio.'),
  (146, 2, 'Quando vai chover, o céu fica cinza e escuro.', 'When it''s going to rain, the sky turns gray and dark.', 'Wenn es gleich regnet, wird der Himmel grau und dunkel.', 'Quando sta per piovere, il cielo diventa grigio e scuro.'),
  (147, 1, 'O urso é marrom.', 'The bear is brown.', 'Der Bär ist braun.', 'L''orso è marrone.'),
  (147, 2, 'O cavalo marrom come capim perto da cerca.', 'The brown horse eats grass near the fence.', 'Das braune Pferd frisst am Zaun Gras.', 'Il cavallo marrone mangia l''erba vicino al recinto.'),
  (148, 1, 'A roda é um círculo.', 'The wheel is a circle.', 'Das Rad ist ein Kreis.', 'La ruota è un cerchio.'),
  (148, 2, 'As crianças fazem um círculo e dão as mãos.', 'The children make a circle and hold hands.', 'Die Kinder machen einen Kreis und geben sich die Hände.', 'I bambini fanno un cerchio e si danno la mano.'),
  (149, 1, 'A janela é um quadrado.', 'The window is a square.', 'Das Fenster ist ein Quadrat.', 'La finestra è un quadrato.'),
  (149, 2, 'Eu desenho um quadrado e um triângulo para fazer uma casa.', 'I draw a square and a triangle to make a house.', 'Ich male ein Quadrat und ein Dreieck und mache daraus ein Haus.', 'Disegno un quadrato e un triangolo per fare una casa.'),
  (150, 1, 'O triângulo tem três lados.', 'The triangle has three sides.', 'Das Dreieck hat drei Seiten.', 'Il triangolo ha tre lati.'),
  (150, 2, 'O pedaço de pizza tem forma de triângulo.', 'The slice of pizza is shaped like a triangle.', 'Das Pizzastück hat die Form eines Dreiecks.', 'La fetta di pizza ha la forma di un triangolo.'),
  (151, 1, 'A porta é um retângulo.', 'The door is a rectangle.', 'Die Tür ist ein Rechteck.', 'La porta è un rettangolo.'),
  (151, 2, 'O livro e o celular têm forma de retângulo.', 'The book and the phone are shaped like a rectangle.', 'Das Buch und das Handy haben die Form eines Rechtecks.', 'Il libro e il telefono hanno la forma di un rettangolo.'),
  (152, 1, 'Eu desenho uma estrela.', 'I draw a star.', 'Ich male einen Stern.', 'Disegno una stella.'),
  (152, 2, 'A professora cola uma estrela dourada no meu caderno.', 'The teacher sticks a gold star in my notebook.', 'Die Lehrerin klebt einen goldenen Stern in mein Heft.', 'La maestra attacca una stella dorata sul mio quaderno.'),
  (153, 1, 'Eu desenho um coração.', 'I draw a heart.', 'Ich male ein Herz.', 'Disegno un cuore.'),
  (153, 2, 'Eu faço um cartão com um coração vermelho para a vovó.', 'I make a card with a red heart for Grandma.', 'Ich bastle für Oma eine Karte mit einem roten Herz.', 'Faccio un biglietto con un cuore rosso per la nonna.'),
  (154, 1, 'A pipa é um losango.', 'The kite is a diamond.', 'Der Drachen ist eine Raute.', 'L''aquilone è un rombo.'),
  (154, 2, 'A minha pipa tem forma de losango e um rabo comprido.', 'My kite is shaped like a diamond and has a long tail.', 'Mein Drachen hat die Form einer Raute und einen langen Schwanz.', 'Il mio aquilone ha la forma di un rombo e una coda lunga.'),
  (155, 1, 'O ovo é oval.', 'The egg is oval.', 'Das Ei ist oval.', 'L''uovo è ovale.'),
  (155, 2, 'O espelho do banheiro tem forma oval.', 'The bathroom mirror is oval.', 'Der Spiegel im Badezimmer ist oval.', 'Lo specchio del bagno è ovale.'),
  (156, 1, 'A ambulância tem uma cruz.', 'The ambulance has a cross.', 'Der Krankenwagen hat ein Kreuz.', 'L''ambulanza ha una croce.'),
  (156, 2, 'No mapa do tesouro, a cruz mostra onde cavar.', 'On the treasure map, the cross shows where to dig.', 'Auf der Schatzkarte zeigt das Kreuz, wo man graben muss.', 'Sulla mappa del tesoro la croce indica dove scavare.'),
  (157, 1, 'A seta aponta para cima.', 'The arrow points up.', 'Der Pfeil zeigt nach oben.', 'La freccia indica in alto.'),
  (157, 2, 'A seta na placa mostra o caminho para o parque.', 'The arrow on the sign shows the way to the park.', 'Der Pfeil auf dem Schild zeigt den Weg zum Park.', 'La freccia sul cartello indica la strada per il parco.'),
  (158, 1, 'O hexágono tem seis lados.', 'The hexagon has six sides.', 'Das Sechseck hat sechs Seiten.', 'L''esagono ha sei lati.'),
  (158, 2, 'As abelhas guardam o mel em casinhas com forma de hexágono.', 'Bees keep honey in little rooms shaped like a hexagon.', 'Die Bienen bewahren den Honig in Waben auf, die wie ein Sechseck aussehen.', 'Le api conservano il miele in celle a forma di esagono.'),
  (159, 1, 'O pentágono tem cinco lados.', 'The pentagon has five sides.', 'Das Fünfeck hat fünf Seiten.', 'Il pentagono ha cinque lati.'),
  (159, 2, 'Eu conto os cinco lados do pentágono com o dedo.', 'I count the five sides of the pentagon with my finger.', 'Ich zähle mit dem Finger die fünf Seiten des Fünfecks.', 'Conto con il dito i cinque lati del pentagono.'),
  (160, 1, 'O sapo pula.', 'The frog jumps.', 'Der Frosch springt.', 'La rana salta.'),
  (160, 2, 'Eu pulo na cama elástica com os meus amigos.', 'I jump on the trampoline with my friends.', 'Ich springe mit meinen Freunden auf dem Trampolin.', 'Salto sul tappeto elastico con i miei amici.'),
  (161, 1, 'Eu abraço a mamãe.', 'I hug Mom.', 'Ich umarme Mama.', 'Abbraccio la mamma.'),
  (161, 2, 'Quando o vovô chega, eu corro para abraçar ele.', 'When Grandpa arrives, I run to hug him.', 'Wenn Opa kommt, renne ich hin, um ihn zu umarmen.', 'Quando arriva il nonno, corro ad abbracciarlo.'),
  (162, 1, 'Eu como a fruta.', 'I eat the fruit.', 'Ich esse das Obst.', 'Mangio la frutta.'),
  (162, 2, 'Na hora do almoço, a família come junta na mesa.', 'At lunchtime, the family eats together at the table.', 'Zum Mittagessen isst die Familie zusammen am Tisch.', 'All''ora di pranzo la famiglia mangia insieme a tavola.'),
  (163, 1, 'Eu bebo água.', 'I drink water.', 'Ich trinke Wasser.', 'Bevo l''acqua.'),
  (163, 2, 'O cachorro bebe água na tigela depois de correr.', 'The dog drinks water from the bowl after running.', 'Der Hund trinkt nach dem Rennen Wasser aus der Schüssel.', 'Il cane beve l''acqua dalla ciotola dopo aver corso.'),
  (164, 1, 'O bebê dorme.', 'The baby sleeps.', 'Das Baby schläft.', 'Il bambino dorme.'),
  (164, 2, 'O gato dorme o dia todo em cima do sofá.', 'The cat sleeps all day on top of the sofa.', 'Die Katze schläft den ganzen Tag auf dem Sofa.', 'Il gatto dorme tutto il giorno sul divano.'),
  (165, 1, 'O cachorro corre.', 'The dog runs.', 'Der Hund rennt.', 'Il cane corre.'),
  (165, 2, 'Eu corro rápido no parque para pegar a bola.', 'I run fast in the park to catch the ball.', 'Ich renne schnell durch den Park, um den Ball zu fangen.', 'Corro veloce nel parco per prendere la palla.'),
  (166, 1, 'Eu brinco com o gato.', 'I play with the cat.', 'Ich spiele mit der Katze.', 'Gioco con il gatto.'),
  (166, 2, 'Depois da escola, eu brinco de esconde-esconde no quintal.', 'After school, I play hide-and-seek in the yard.', 'Nach der Schule spiele ich im Garten Verstecken.', 'Dopo la scuola gioco a nascondino in cortile.'),
  (167, 1, 'Eu sento na cadeira.', 'I sit on the chair.', 'Ich sitze auf dem Stuhl.', 'Mi siedo sulla sedia.'),
  (167, 2, 'Na escola, eu sento perto da janela e do meu amigo.', 'At school, I sit by the window and next to my friend.', 'In der Schule sitze ich am Fenster neben meinem Freund.', 'A scuola mi siedo vicino alla finestra e al mio amico.'),
  (168, 1, 'Eu ando devagar.', 'I walk slowly.', 'Ich gehe langsam.', 'Cammino piano.'),
  (168, 2, 'Eu ando de mãos dadas com a vovó até a padaria.', 'I walk hand in hand with Grandma to the bakery.', 'Ich gehe mit Oma an der Hand zur Bäckerei.', 'Cammino mano nella mano con la nonna fino al panificio.'),
  (169, 1, 'O pássaro canta.', 'The bird sings.', 'Der Vogel singt.', 'L''uccello canta.'),
  (169, 2, 'Eu canto parabéns bem alto na festa do meu amigo.', 'I sing happy birthday very loudly at my friend''s party.', 'Ich singe auf der Party meines Freundes ganz laut Happy Birthday.', 'Canto tanti auguri a voce alta alla festa del mio amico.'),
  (170, 1, 'O bebê chora.', 'The baby cries.', 'Das Baby weint.', 'Il bambino piange.'),
  (170, 2, 'O bebê chora quando está com fome ou com sono.', 'The baby cries when he is hungry or sleepy.', 'Das Baby weint, wenn es Hunger hat oder müde ist.', 'Il bambino piange quando ha fame o sonno.'),
  (171, 1, 'O palhaço faz a gente rir.', 'The clown makes us laugh.', 'Der Clown bringt uns zum Lachen.', 'Il pagliaccio ci fa ridere.'),
  (171, 2, 'Eu rio muito quando o papai faz cócegas na minha barriga.', 'I laugh a lot when Dad tickles my belly.', 'Ich lache viel, wenn Papa meinen Bauch kitzelt.', 'Rido tanto quando papà mi fa il solletico sulla pancia.'),
  (172, 1, 'A mamãe lê um livro.', 'Mom reads a book.', 'Mama liest ein Buch.', 'La mamma legge un libro.'),
  (172, 2, 'Antes de dormir, o papai lê uma história de dragão.', 'Before bed, Dad reads a story about a dragon.', 'Vor dem Schlafen liest Papa eine Geschichte über einen Drachen vor.', 'Prima di dormire papà legge una storia sui draghi.'),
  (173, 1, 'Eu escrevo meu nome.', 'I write my name.', 'Ich schreibe meinen Namen.', 'Scrivo il mio nome.'),
  (173, 2, 'Eu escrevo uma carta para o vovô com lápis colorido.', 'I write a letter to Grandpa with colored pencils.', 'Ich schreibe Opa einen Brief mit Buntstiften.', 'Scrivo una lettera al nonno con le matite colorate.'),
  (174, 1, 'Eu lavo as mãos.', 'I wash my hands.', 'Ich wasche mir die Hände.', 'Mi lavo le mani.'),
  (174, 2, 'Antes de comer, eu lavo as mãos com água e sabonete.', 'Before eating, I wash my hands with water and soap.', 'Vor dem Essen wasche ich mir die Hände mit Wasser und Seife.', 'Prima di mangiare mi lavo le mani con acqua e sapone.'),
  (175, 1, 'Olhe para cima.', 'Look up.', 'Schau nach oben.', 'Guarda in alto.'),
  (175, 2, 'Eu olho pela janela para ver se está chovendo.', 'I look out the window to see if it''s raining.', 'Ich schaue aus dem Fenster, ob es regnet.', 'Guardo dalla finestra per vedere se piove.'),
  (176, 1, 'Eu ouço música.', 'I listen to music.', 'Ich höre Musik.', 'Ascolto la musica.'),
  (176, 2, 'Eu ouço o barulho da chuva no telhado de noite.', 'I listen to the sound of the rain on the roof at night.', 'Nachts höre ich den Regen auf dem Dach.', 'Di notte ascolto il rumore della pioggia sul tetto.'),
  (177, 1, 'O papagaio fala.', 'The parrot talks.', 'Der Papagei spricht.', 'Il pappagallo parla.'),
  (177, 2, 'Eu falo com a vovó pelo telefone todo domingo.', 'I talk to Grandma on the phone every Sunday.', 'Ich spreche jeden Sonntag mit Oma am Telefon.', 'Parlo con la nonna al telefono ogni domenica.'),
  (178, 1, 'Eu danço na sala.', 'I dance in the living room.', 'Ich tanze im Wohnzimmer.', 'Ballo in soggiorno.'),
  (178, 2, 'Na festa, todo mundo dança quando toca a música.', 'At the party, everyone dances when the music plays.', 'Auf der Party tanzen alle, wenn die Musik spielt.', 'Alla festa tutti ballano quando parte la musica.'),
  (179, 1, 'O pássaro voa.', 'The bird flies.', 'Der Vogel fliegt.', 'L''uccello vola.'),
  (179, 2, 'O avião voa bem alto, acima das nuvens.', 'The plane flies very high, above the clouds.', 'Das Flugzeug fliegt ganz hoch über den Wolken.', 'L''aereo vola altissimo, sopra le nuvole.'),
  (180, 1, 'O peixe nada.', 'The fish swims.', 'Der Fisch schwimmt.', 'Il pesce nuota.'),
  (180, 2, 'No verão, eu nado na piscina com boia.', 'In summer, I swim in the pool with armbands.', 'Im Sommer schwimme ich mit Schwimmflügeln im Pool.', 'D''estate nuoto in piscina con i braccioli.'),
  (181, 1, 'Eu chuto a bola.', 'I kick the ball.', 'Ich schieße den Ball.', 'Calcio la palla.'),
  (181, 2, 'Eu chuto a bola com força e faço um gol.', 'I kick the ball hard and score a goal.', 'Ich schieße den Ball fest und mache ein Tor.', 'Calcio forte la palla e faccio gol.'),
  (182, 1, 'Eu pego a bola.', 'I catch the ball.', 'Ich fange den Ball.', 'Prendo la palla.'),
  (182, 2, 'O papai joga a bola e eu pego com as duas mãos.', 'Dad throws the ball and I catch it with both hands.', 'Papa wirft den Ball und ich fange ihn mit beiden Händen.', 'Papà lancia la palla e io la prendo con tutte e due le mani.'),
  (183, 1, 'A folha cai.', 'The leaf falls.', 'Das Blatt fällt.', 'La foglia cade.'),
  (183, 2, 'O copo caiu da mesa, mas não quebrou.', 'The glass fell off the table, but it didn''t break.', 'Das Glas ist vom Tisch gefallen, aber nicht kaputtgegangen.', 'Il bicchiere è caduto dal tavolo, ma non si è rotto.'),
  (184, 1, 'O macaco sobe na árvore.', 'The monkey climbs the tree.', 'Der Affe klettert auf den Baum.', 'La scimmia sale sull''albero.'),
  (184, 2, 'No parquinho, eu subo a escada para descer no escorregador.', 'At the playground, I climb the ladder to go down the slide.', 'Auf dem Spielplatz klettere ich die Leiter hoch, um zu rutschen.', 'Al parco giochi salgo la scaletta per scendere dallo scivolo.'),
  (185, 1, 'O papai cozinha.', 'Dad cooks.', 'Papa kocht.', 'Papà cucina.'),
  (185, 2, 'No domingo, eu ajudo a vovó a cozinhar o almoço.', 'On Sunday, I help Grandma cook lunch.', 'Am Sonntag helfe ich Oma, das Mittagessen zu kochen.', 'La domenica aiuto la nonna a cucinare il pranzo.'),
  (186, 1, 'Eu corto o papel.', 'I cut the paper.', 'Ich schneide das Papier.', 'Taglio la carta.'),
  (186, 2, 'Eu corto um coração de papel com a tesoura.', 'I cut out a paper heart with the scissors.', 'Ich schneide mit der Schere ein Herz aus Papier aus.', 'Ritaglio un cuore di carta con le forbici.'),
  (187, 1, 'Eu pinto um sol.', 'I paint a sun.', 'Ich male eine Sonne.', 'Dipingo un sole.'),
  (187, 2, 'Eu pinto um arco-íris com sete cores diferentes.', 'I paint a rainbow with seven different colors.', 'Ich male einen Regenbogen mit sieben verschiedenen Farben.', 'Dipingo un arcobaleno con sette colori diversi.'),
  (188, 1, 'Eu limpo a mesa.', 'I clean the table.', 'Ich putze den Tisch.', 'Pulisco il tavolo.'),
  (188, 2, 'Depois de brincar, eu limpo o quarto e guardo tudo.', 'After playing, I clean my room and put everything away.', 'Nach dem Spielen räume ich mein Zimmer auf und mache alles sauber.', 'Dopo aver giocato pulisco la camera e metto tutto a posto.'),
  (189, 1, 'Eu conto até dez.', 'I count to ten.', 'Ich zähle bis zehn.', 'Conto fino a dieci.'),
  (189, 2, 'No esconde-esconde, eu conto até dez de olhos fechados.', 'In hide-and-seek, I count to ten with my eyes closed.', 'Beim Verstecken zähle ich mit geschlossenen Augen bis zehn.', 'A nascondino conto fino a dieci con gli occhi chiusi.'),
  (190, 1, 'Eu aceno tchau.', 'I wave goodbye.', 'Ich winke zum Abschied.', 'Saluto con la mano.'),
  (190, 2, 'Da janela do carro, eu aceno para o vovô.', 'From the car window, I wave to Grandpa.', 'Aus dem Autofenster winke ich Opa zu.', 'Dal finestrino della macchina saluto il nonno con la mano.'),
  (191, 1, 'Eu abro a porta.', 'I open the door.', 'Ich öffne die Tür.', 'Apro la porta.'),
  (191, 2, 'Eu abro o presente com cuidado para ver o que tem dentro.', 'I open the present carefully to see what''s inside.', 'Ich öffne das Geschenk vorsichtig, um zu sehen, was drin ist.', 'Apro il regalo con attenzione per vedere cosa c''è dentro.'),
  (192, 1, 'Eu fecho a janela.', 'I close the window.', 'Ich schließe das Fenster.', 'Chiudo la finestra.'),
  (192, 2, 'Quando começa a chover, eu fecho a janela do quarto.', 'When it starts to rain, I close the bedroom window.', 'Wenn es anfängt zu regnen, schließe ich das Fenster im Zimmer.', 'Quando comincia a piovere, chiudo la finestra della camera.'),
  (193, 1, 'Eu empurro o carrinho.', 'I push the stroller.', 'Ich schiebe den Wagen.', 'Spingo il passeggino.'),
  (193, 2, 'Eu empurro o balanço para a minha amiga ir bem alto.', 'I push the swing so my friend goes up really high.', 'Ich schiebe die Schaukel an, damit meine Freundin ganz hoch fliegt.', 'Spingo l''altalena così la mia amica va altissimo.'),
  (194, 1, 'Eu puxo a corda.', 'I pull the rope.', 'Ich ziehe am Seil.', 'Tiro la corda.'),
  (194, 2, 'O cachorro puxa a guia porque quer correr no parque.', 'The dog pulls on the leash because it wants to run in the park.', 'Der Hund zieht an der Leine, weil er im Park rennen will.', 'Il cane tira il guinzaglio perché vuole correre nel parco.'),
  (195, 1, 'Eu jogo a bola.', 'I throw the ball.', 'Ich werfe den Ball.', 'Lancio la palla.'),
  (195, 2, 'Eu jogo a bola bem longe e o cachorro busca.', 'I throw the ball really far and the dog fetches it.', 'Ich werfe den Ball ganz weit und der Hund holt ihn.', 'Lancio la palla lontano e il cane la riporta.'),
  (196, 1, 'Eu desenho um gato.', 'I draw a cat.', 'Ich zeichne eine Katze.', 'Disegno un gatto.'),
  (196, 2, 'Eu desenho a minha família inteira na folha branca.', 'I draw my whole family on the white sheet of paper.', 'Ich zeichne meine ganze Familie auf das weiße Blatt.', 'Disegno tutta la mia famiglia sul foglio bianco.'),
  (197, 1, 'Eu escovo os dentes.', 'I brush my teeth.', 'Ich putze mir die Zähne.', 'Mi spazzolo i denti.'),
  (197, 2, 'Depois do jantar, eu escovo os dentes com a escova azul.', 'After dinner, I brush my teeth with the blue toothbrush.', 'Nach dem Abendessen putze ich mir mit der blauen Zahnbürste die Zähne.', 'Dopo cena mi spazzolo i denti con lo spazzolino blu.'),
  (198, 1, 'Eu cheiro a flor.', 'I smell the flower.', 'Ich rieche an der Blume.', 'Annuso il fiore.'),
  (198, 2, 'O cachorro cheira tudo no caminho até o parque.', 'The dog smells everything on the way to the park.', 'Der Hund riecht auf dem Weg zum Park an allem.', 'Il cane annusa tutto lungo la strada per il parco.'),
  (199, 1, 'Eu dou um presente.', 'I give a present.', 'Ich gebe ein Geschenk.', 'Do un regalo.'),
  (199, 2, 'Eu dou metade do meu biscoito para o meu amigo.', 'I give half of my cookie to my friend.', 'Ich gebe meinem Freund die Hälfte von meinem Keks.', 'Do metà del mio biscotto al mio amico.'),
  (200, 1, 'Eu planto uma semente.', 'I plant a seed.', 'Ich pflanze einen Samen.', 'Pianto un seme.'),
  (200, 2, 'Eu planto uma flor no jardim e rego todo dia.', 'I plant a flower in the garden and water it every day.', 'Ich pflanze eine Blume im Garten und gieße sie jeden Tag.', 'Pianto un fiore in giardino e lo annaffio ogni giorno.'),
  (201, 1, 'O cachorro cava.', 'The dog digs.', 'Der Hund gräbt.', 'Il cane scava.'),
  (201, 2, 'Eu cavo um buraco na areia com a pazinha.', 'I dig a hole in the sand with my little shovel.', 'Ich grabe mit der kleinen Schaufel ein Loch in den Sand.', 'Scavo una buca nella sabbia con la paletta.'),
  (202, 1, 'Eu aponto para a lua.', 'I point at the moon.', 'Ich zeige auf den Mond.', 'Indico la luna.'),
  (202, 2, 'Eu aponto para o avião que passa lá no céu.', 'I point at the plane flying across the sky.', 'Ich zeige auf das Flugzeug, das oben am Himmel fliegt.', 'Indico l''aereo che passa nel cielo.'),
  (203, 1, 'Eu bato na porta.', 'I knock on the door.', 'Ich klopfe an die Tür.', 'Busso alla porta.'),
  (203, 2, 'Antes de entrar no quarto, eu bato na porta.', 'Before I go into the room, I knock on the door.', 'Bevor ich ins Zimmer gehe, klopfe ich an die Tür.', 'Prima di entrare in camera busso alla porta.'),
  (204, 1, 'O papai carrega a mala.', 'Dad carries the suitcase.', 'Papa trägt den Koffer.', 'Papà porta la valigia.'),
  (204, 2, 'A formiga carrega uma folha maior do que ela.', 'The ant carries a leaf bigger than itself.', 'Die Ameise trägt ein Blatt, das größer ist als sie.', 'La formica porta una foglia più grande di lei.'),
  (205, 1, 'O bebê sorri.', 'The baby smiles.', 'Das Baby lächelt.', 'Il bambino sorride.'),
  (205, 2, 'Eu sorrio para a foto com a minha família.', 'I smile for the photo with my family.', 'Ich lächle mit meiner Familie für das Foto.', 'Sorrido per la foto con la mia famiglia.'),
  (206, 1, 'Não precisa gritar.', 'No need to shout.', 'Du musst nicht schreien.', 'Non c''è bisogno di urlare.'),
  (206, 2, 'No jogo de futebol, a torcida grita gol bem alto.', 'At the soccer game, the fans shout goal really loudly.', 'Beim Fußballspiel schreien die Fans ganz laut Tor.', 'Alla partita di calcio i tifosi urlano gol a squarciagola.'),
  (207, 1, 'Eu sopro a vela.', 'I blow out the candle.', 'Ich puste die Kerze aus.', 'Soffio sulla candela.'),
  (207, 2, 'Eu faço um pedido e sopro as velas do bolo.', 'I make a wish and blow out the candles on the cake.', 'Ich wünsche mir etwas und puste die Kerzen auf dem Kuchen aus.', 'Esprimo un desiderio e soffio sulle candeline della torta.'),
  (208, 1, 'Eu beijo o bebê.', 'I kiss the baby.', 'Ich küsse das Baby.', 'Bacio il bambino.'),
  (208, 2, 'A mamãe beija minha bochecha antes de eu ir para a escola.', 'Mom kisses my cheek before I go to school.', 'Mama küsst meine Wange, bevor ich in die Schule gehe.', 'La mamma mi bacia la guancia prima che io vada a scuola.'),
  (209, 1, 'Eu penteio o cabelo.', 'I comb my hair.', 'Ich kämme meine Haare.', 'Mi pettino i capelli.'),
  (209, 2, 'A mamãe penteia o meu cabelo depois do banho.', 'Mom combs my hair after the bath.', 'Mama kämmt mir nach dem Baden die Haare.', 'La mamma mi pettina i capelli dopo il bagno.'),
  (210, 1, 'Eu me visto.', 'I get dressed.', 'Ich ziehe mich an.', 'Mi vesto.'),
  (210, 2, 'De manhã, eu me visto rápido para ir à escola.', 'In the morning, I get dressed quickly to go to school.', 'Morgens ziehe ich mich schnell an, um in die Schule zu gehen.', 'La mattina mi vesto in fretta per andare a scuola.'),
  (211, 1, 'Eu rego a planta.', 'I water the plant.', 'Ich gieße die Pflanze.', 'Annaffio la pianta.'),
  (211, 2, 'Todo dia de manhã, eu rego as flores do jardim.', 'Every morning, I water the flowers in the garden.', 'Jeden Morgen gieße ich die Blumen im Garten.', 'Ogni mattina annaffio i fiori del giardino.'),
  (212, 1, 'Eu colo o papel.', 'I glue the paper.', 'Ich klebe das Papier.', 'Incollo la carta.'),
  (212, 2, 'Eu colo estrelas brilhantes no teto do meu quarto.', 'I stick shiny stars on my bedroom ceiling.', 'Ich klebe leuchtende Sterne an die Decke in meinem Zimmer.', 'Incollo stelle luminose sul soffitto della mia camera.'),
  (213, 1, 'Não rasgue o livro.', 'Don''t tear the book.', 'Zerreiß das Buch nicht.', 'Non strappare il libro.'),
  (213, 2, 'Eu rasgo o papel de presente com muita vontade.', 'I tear the wrapping paper off with lots of excitement.', 'Ich reiße das Geschenkpapier voller Freude auf.', 'Strappo la carta del regalo con tanta voglia.'),
  (214, 1, 'Todo mundo aplaude.', 'Everyone claps.', 'Alle klatschen.', 'Tutti applaudono.'),
  (214, 2, 'No fim do teatro, a gente aplaude bem forte.', 'At the end of the play, we clap really loudly.', 'Am Ende des Theaterstücks klatschen wir ganz laut.', 'Alla fine dello spettacolo applaudiamo fortissimo.'),
  (215, 1, 'Eu acordo cedo.', 'I wake up early.', 'Ich wache früh auf.', 'Mi sveglio presto.'),
  (215, 2, 'Eu acordo quando o sol entra pela janela.', 'I wake up when the sun comes in through the window.', 'Ich wache auf, wenn die Sonne durchs Fenster scheint.', 'Mi sveglio quando il sole entra dalla finestra.'),
  (216, 1, 'Eu procuro o gato.', 'I look for the cat.', 'Ich suche die Katze.', 'Cerco il gatto.'),
  (216, 2, 'Eu procuro o meu sapato debaixo da cama.', 'I look for my shoe under the bed.', 'Ich suche meinen Schuh unter dem Bett.', 'Cerco la mia scarpa sotto il letto.'),
  (217, 1, 'O gato se esconde.', 'The cat hides.', 'Die Katze versteckt sich.', 'Il gatto si nasconde.'),
  (217, 2, 'Eu me escondo atrás da cortina no esconde-esconde.', 'I hide behind the curtain in hide-and-seek.', 'Beim Verstecken verstecke ich mich hinter dem Vorhang.', 'A nascondino mi nascondo dietro la tenda.'),
  (218, 1, 'O time ganha.', 'The team wins.', 'Die Mannschaft gewinnt.', 'La squadra vince.'),
  (218, 2, 'O meu time ganha o jogo e todo mundo comemora.', 'My team wins the game and everyone celebrates.', 'Meine Mannschaft gewinnt das Spiel und alle feiern.', 'La mia squadra vince la partita e tutti festeggiano.'),
  (219, 1, 'Eu meço a mesa.', 'I measure the table.', 'Ich messe den Tisch.', 'Misuro il tavolo.'),
  (219, 2, 'O papai mede a minha altura na porta do quarto.', 'Dad measures my height on the bedroom door.', 'Papa misst meine Größe an der Zimmertür.', 'Papà misura la mia altezza sulla porta della camera.'),
  (220, 1, 'Eu misturo a massa.', 'I mix the batter.', 'Ich rühre den Teig.', 'Mescolo l''impasto.'),
  (220, 2, 'Eu misturo o leite com o chocolate na caneca.', 'I mix the milk with the chocolate in the mug.', 'Ich rühre die Milch mit dem Kakao im Becher um.', 'Mescolo il latte con il cioccolato nel tazzone.'),
  (221, 1, 'Eu acendo a luz.', 'I turn on the light.', 'Ich mache das Licht an.', 'Accendo la luce.'),
  (221, 2, 'Quando fica escuro, eu acendo a luz do quarto.', 'When it gets dark, I turn on the bedroom light.', 'Wenn es dunkel wird, mache ich das Licht im Zimmer an.', 'Quando fa buio, accendo la luce della camera.'),
  (222, 1, 'O carro para.', 'The car stops.', 'Das Auto hält an.', 'La macchina si ferma.'),
  (222, 2, 'O ônibus para no ponto para as pessoas entrarem.', 'The bus stops at the bus stop so people can get on.', 'Der Bus hält an der Haltestelle, damit die Leute einsteigen können.', 'L''autobus si ferma alla fermata per far salire la gente.'),
  (223, 1, 'Eu desço a escada.', 'I go down the stairs.', 'Ich gehe die Treppe runter.', 'Scendo le scale.'),
  (223, 2, 'Eu desço no escorregador bem rápido e dou risada.', 'I go down the slide really fast and laugh.', 'Ich rutsche ganz schnell die Rutsche runter und lache.', 'Scendo dallo scivolo velocissimo e rido.'),
  (224, 1, 'O bebê engatinha.', 'The baby crawls.', 'Das Baby krabbelt.', 'Il bambino gattona.'),
  (224, 2, 'O bebê engatinha pela sala atrás da bola.', 'The baby crawls across the living room after the ball.', 'Das Baby krabbelt durch das Wohnzimmer hinter dem Ball her.', 'Il bambino gattona per il soggiorno dietro alla palla.'),
  (225, 1, 'Eu espero a minha vez.', 'I wait for my turn.', 'Ich warte, bis ich dran bin.', 'Aspetto il mio turno.'),
  (225, 2, 'Eu espero o ônibus da escola com a mamãe.', 'I wait for the school bus with Mom.', 'Ich warte mit Mama auf den Schulbus.', 'Aspetto lo scuolabus con la mamma.'),
  (226, 1, 'Eu ajudo o papai.', 'I help Dad.', 'Ich helfe Papa.', 'Aiuto papà.'),
  (226, 2, 'Eu ajudo a vovó a carregar as compras do mercado.', 'I help Grandma carry the groceries from the market.', 'Ich helfe Oma, die Einkäufe vom Markt zu tragen.', 'Aiuto la nonna a portare la spesa dal mercato.'),
  (227, 1, 'Eu escolho um livro.', 'I choose a book.', 'Ich wähle ein Buch.', 'Scelgo un libro.'),
  (227, 2, 'Na sorveteria, eu escolho sorvete de chocolate.', 'At the ice cream shop, I choose chocolate ice cream.', 'In der Eisdiele wähle ich Schokoladeneis.', 'In gelateria scelgo il gelato al cioccolato.'),
  (228, 1, 'Eu sonho com dragões.', 'I dream about dragons.', 'Ich träume von Drachen.', 'Sogno i draghi.'),
  (228, 2, 'De noite, eu sonho que voo como um pássaro.', 'At night, I dream that I fly like a bird.', 'Nachts träume ich, dass ich wie ein Vogel fliege.', 'Di notte sogno di volare come un uccello.'),
  (229, 1, 'O copo quebra.', 'The glass breaks.', 'Das Glas zerbricht.', 'Il bicchiere si rompe.'),
  (229, 2, 'Cuidado com o prato, ele pode quebrar se cair.', 'Careful with the plate, it can break if it falls.', 'Vorsicht mit dem Teller, er kann zerbrechen, wenn er runterfällt.', 'Attento al piatto, si può rompere se cade.'),
  (230, 1, 'O vovô conserta.', 'Grandpa fixes it.', 'Opa repariert es.', 'Il nonno lo ripara.'),
  (230, 2, 'O vovô conserta a roda da minha bicicleta.', 'Grandpa fixes the wheel on my bike.', 'Opa repariert das Rad an meinem Fahrrad.', 'Il nonno ripara la ruota della mia bicicletta.'),
  (231, 1, 'Eu martelo o prego.', 'I hammer the nail.', 'Ich hämmere den Nagel ein.', 'Martello il chiodo.'),
  (231, 2, 'O papai martela um prego para pendurar o quadro.', 'Dad hammers a nail to hang the picture.', 'Papa hämmert einen Nagel in die Wand, um das Bild aufzuhängen.', 'Papà martella un chiodo per appendere il quadro.'),
  (232, 1, 'O vovô pesca.', 'Grandpa fishes.', 'Opa angelt.', 'Il nonno pesca.'),
  (232, 2, 'Eu pesco no lago com o vovô no domingo.', 'I go fishing at the lake with Grandpa on Sunday.', 'Am Sonntag angle ich mit Opa am See.', 'La domenica pesco al lago con il nonno.'),
  (233, 1, 'A mamãe dirige.', 'Mom drives.', 'Mama fährt.', 'La mamma guida.'),
  (233, 2, 'O papai dirige o carro até a casa da vovó.', 'Dad drives the car to Grandma''s house.', 'Papa fährt mit dem Auto zu Oma.', 'Papà guida la macchina fino a casa della nonna.'),
  (234, 1, 'O papai volta para casa.', 'Dad comes back home.', 'Papa kommt nach Hause zurück.', 'Papà torna a casa.'),
  (234, 2, 'Depois da viagem, a gente volta para casa de avião.', 'After the trip, we come back home by plane.', 'Nach der Reise fliegen wir mit dem Flugzeug nach Hause zurück.', 'Dopo il viaggio torniamo a casa in aereo.'),
  (235, 1, 'Eu entro em casa.', 'I go into the house.', 'Ich gehe ins Haus.', 'Entro in casa.'),
  (235, 2, 'Eu tiro o sapato antes de entrar no quarto.', 'I take off my shoes before I go into my room.', 'Ich ziehe die Schuhe aus, bevor ich ins Zimmer gehe.', 'Mi tolgo le scarpe prima di entrare in camera.'),
  (236, 1, 'Eu saio de casa.', 'I leave the house.', 'Ich gehe aus dem Haus.', 'Esco di casa.'),
  (236, 2, 'Quando para de chover, eu saio para brincar lá fora.', 'When it stops raining, I go out to play outside.', 'Wenn es aufhört zu regnen, gehe ich raus zum Spielen.', 'Quando smette di piovere, esco a giocare fuori.'),
  (237, 1, 'A vovó costura.', 'Grandma sews.', 'Oma näht.', 'La nonna cuce.'),
  (237, 2, 'A vovó costura um botão na minha camiseta.', 'Grandma sews a button on my t-shirt.', 'Oma näht einen Knopf an mein T-Shirt.', 'La nonna cuce un bottone sulla mia maglietta.'),
  (238, 1, 'Eu remo o barco.', 'I row the boat.', 'Ich rudere das Boot.', 'Remo la barca.'),
  (238, 2, 'O papai e eu remamos o barco no lago.', 'Dad and I row the boat on the lake.', 'Papa und ich rudern mit dem Boot über den See.', 'Papà e io remiamo con la barca sul lago.'),
  (239, 1, 'O pião gira.', 'The top spins.', 'Der Kreisel dreht sich.', 'La trottola gira.'),
  (239, 2, 'Eu giro com os braços abertos até a cabeça rodar.', 'I spin with my arms open until I get dizzy.', 'Ich drehe mich mit ausgebreiteten Armen, bis mir schwindlig wird.', 'Giro con le braccia aperte finché mi gira la testa.'),
  (240, 1, 'Eu tenho um cachorro.', 'I have one dog.', 'Ich habe einen Hund.', 'Ho un cane.'),
  (240, 2, 'No céu tem um sol e muitas nuvens.', 'In the sky there is one sun and many clouds.', 'Am Himmel gibt es eine Sonne und viele Wolken.', 'Nel cielo c''è un sole e tante nuvole.'),
  (241, 1, 'Eu tenho dois olhos.', 'I have two eyes.', 'Ich habe zwei Augen.', 'Ho due occhi.'),
  (241, 2, 'A bicicleta tem duas rodas e a moto também.', 'The bicycle has two wheels, and so does the motorcycle.', 'Das Fahrrad hat zwei Räder und das Motorrad auch.', 'La bicicletta ha due ruote e anche la moto.'),
  (242, 1, 'Eu tenho três anos.', 'I am three years old.', 'Ich bin drei Jahre alt.', 'Ho tre anni.'),
  (242, 2, 'O triângulo tem três lados e três pontas.', 'The triangle has three sides and three corners.', 'Das Dreieck hat drei Seiten und drei Ecken.', 'Il triangolo ha tre lati e tre punte.'),
  (243, 1, 'O cachorro tem quatro patas.', 'The dog has four legs.', 'Der Hund hat vier Beine.', 'Il cane ha quattro zampe.'),
  (243, 2, 'O carro tem quatro rodas e quatro portas.', 'The car has four wheels and four doors.', 'Das Auto hat vier Räder und vier Türen.', 'La macchina ha quattro ruote e quattro porte.'),
  (244, 1, 'Eu tenho cinco anos.', 'I am five years old.', 'Ich bin fünf Jahre alt.', 'Ho cinque anni.'),
  (244, 2, 'Na minha mão tem cinco dedos para contar.', 'My hand has five fingers for counting.', 'An meiner Hand sind fünf Finger zum Zählen.', 'La mia mano ha cinque dita per contare.'),
  (245, 1, 'O inseto tem seis patas.', 'The insect has six legs.', 'Das Insekt hat sechs Beine.', 'L''insetto ha sei zampe.'),
  (245, 2, 'Na caixa tem seis ovos brancos.', 'There are six white eggs in the box.', 'In der Schachtel sind sechs weiße Eier.', 'Nella scatola ci sono sei uova bianche.'),
  (246, 1, 'A semana tem sete dias.', 'The week has seven days.', 'Die Woche hat sieben Tage.', 'La settimana ha sette giorni.'),
  (246, 2, 'O arco-íris tem sete cores bem bonitas.', 'The rainbow has seven beautiful colors.', 'Der Regenbogen hat sieben wunderschöne Farben.', 'L''arcobaleno ha sette colori bellissimi.'),
  (247, 1, 'O polvo tem oito braços.', 'The octopus has eight arms.', 'Der Krake hat acht Arme.', 'Il polpo ha otto tentacoli.'),
  (247, 2, 'A aranha tem oito patas e faz uma teia.', 'The spider has eight legs and makes a web.', 'Die Spinne hat acht Beine und baut ein Netz.', 'Il ragno ha otto zampe e fa la ragnatela.'),
  (248, 1, 'Eu conto até nove.', 'I count to nine.', 'Ich zähle bis neun.', 'Conto fino a nove.'),
  (248, 2, 'O meu irmão vai fazer nove anos no sábado.', 'My brother is turning nine on Saturday.', 'Mein Bruder wird am Samstag neun Jahre alt.', 'Mio fratello compie nove anni sabato.'),
  (249, 1, 'Eu tenho dez dedos.', 'I have ten fingers.', 'Ich habe zehn Finger.', 'Ho dieci dita.'),
  (249, 2, 'No esconde-esconde, eu conto até dez e vou procurar.', 'In hide-and-seek, I count to ten and go looking.', 'Beim Verstecken zähle ich bis zehn und fange an zu suchen.', 'A nascondino conto fino a dieci e vado a cercare.'),
  (250, 1, 'O carro é vermelho.', 'The car is red.', 'Das Auto ist rot.', 'La macchina è rossa.'),
  (250, 2, 'A família vai de carro para a praia no sábado.', 'The family goes to the beach by car on Saturday.', 'Am Samstag fährt die Familie mit dem Auto an den Strand.', 'Il sabato la famiglia va al mare in macchina.'),
  (251, 1, 'O trem é comprido.', 'The train is long.', 'Der Zug ist lang.', 'Il treno è lungo.'),
  (251, 2, 'O trem passa na ponte e apita bem alto.', 'The train crosses the bridge and whistles loudly.', 'Der Zug fährt über die Brücke und pfeift laut.', 'Il treno passa sul ponte e fischia forte.'),
  (252, 1, 'O ônibus é amarelo.', 'The bus is yellow.', 'Der Bus ist gelb.', 'L''autobus è giallo.'),
  (252, 2, 'Eu vou para a escola de ônibus com os meus amigos.', 'I go to school by bus with my friends.', 'Ich fahre mit meinen Freunden mit dem Bus zur Schule.', 'Vado a scuola in autobus con i miei amici.'),
  (253, 1, 'O avião voa.', 'The plane flies.', 'Das Flugzeug fliegt.', 'L''aereo vola.'),
  (253, 2, 'O avião grande leva a gente para visitar a vovó.', 'The big plane takes us to visit Grandma.', 'Das große Flugzeug bringt uns zu Oma.', 'Il grande aereo ci porta a trovare la nonna.'),
  (254, 1, 'O barco flutua.', 'The boat floats.', 'Das Boot schwimmt.', 'La barca galleggia.'),
  (254, 2, 'O barco a vela navega devagar no lago azul.', 'The sailboat glides slowly on the blue lake.', 'Das Segelboot fährt langsam über den blauen See.', 'La barca a vela naviga piano sul lago blu.'),
  (255, 1, 'A moto faz barulho.', 'The motorcycle is loud.', 'Das Motorrad ist laut.', 'La moto fa rumore.'),
  (255, 2, 'O tio anda de moto com capacete na cabeça.', 'My uncle rides his motorcycle with a helmet on his head.', 'Mein Onkel fährt Motorrad mit einem Helm auf dem Kopf.', 'Lo zio va in moto con il casco in testa.'),
  (256, 1, 'O caminhão é grande.', 'The truck is big.', 'Der Lastwagen ist groß.', 'Il camion è grande.'),
  (256, 2, 'O caminhão leva frutas da fazenda para o mercado.', 'The truck takes fruit from the farm to the market.', 'Der Lastwagen bringt Obst vom Bauernhof zum Markt.', 'Il camion porta la frutta dalla fattoria al mercato.'),
  (257, 1, 'O helicóptero voa.', 'The helicopter flies.', 'Der Hubschrauber fliegt.', 'L''elicottero vola.'),
  (257, 2, 'O helicóptero gira as hélices e sobe devagar.', 'The helicopter spins its blades and slowly rises.', 'Der Hubschrauber dreht die Rotoren und steigt langsam auf.', 'L''elicottero fa girare le pale e sale piano.'),
  (258, 1, 'O foguete sobe.', 'The rocket goes up.', 'Die Rakete steigt auf.', 'Il razzo sale.'),
  (258, 2, 'O foguete leva os astronautas até a lua.', 'The rocket takes the astronauts to the moon.', 'Die Rakete bringt die Astronauten zum Mond.', 'Il razzo porta gli astronauti sulla luna.'),
  (259, 1, 'A ambulância chegou.', 'The ambulance is here.', 'Der Krankenwagen ist da.', 'È arrivata l''ambulanza.'),
  (259, 2, 'A ambulância liga a sirene e corre para o hospital.', 'The ambulance turns on its siren and hurries to the hospital.', 'Der Krankenwagen macht die Sirene an und fährt schnell ins Krankenhaus.', 'L''ambulanza accende la sirena e corre all''ospedale.'),
  (260, 1, 'O trator é verde.', 'The tractor is green.', 'Der Traktor ist grün.', 'Il trattore è verde.'),
  (260, 2, 'O agricultor usa o trator para arar a terra.', 'The farmer uses the tractor to plow the land.', 'Der Bauer pflügt mit dem Traktor das Feld.', 'Il contadino usa il trattore per arare la terra.'),
  (261, 1, 'Eu ando de patinete.', 'I ride my scooter.', 'Ich fahre Roller.', 'Vado in monopattino.'),
