  (369, 2, 'O cabelo do papai é curto e o da mamãe é comprido.', 'Dad''s hair is short and Mom''s is long.', 'Papas Haare sind kurz und Mamas sind lang.', 'I capelli di papà sono corti e quelli della mamma sono lunghi.'),
  (370, 1, 'A porta está aberta.', 'The door is open.', 'Die Tür ist offen.', 'La porta è aperta.'),
  (370, 2, 'A padaria está aberta e tem pão quentinho.', 'The bakery is open and has warm bread.', 'Die Bäckerei ist offen und hat warmes Brot.', 'Il panificio è aperto e ha il pane caldo.'),
  (371, 1, 'A janela está fechada.', 'The window is closed.', 'Das Fenster ist geschlossen.', 'La finestra è chiusa.'),
  (371, 2, 'De noite, o parque fica fechado e escuro.', 'At night, the park is closed and dark.', 'Nachts ist der Park geschlossen und dunkel.', 'Di notte il parco è chiuso e buio.'),
  (372, 1, 'O copo está cheio.', 'The glass is full.', 'Das Glas ist voll.', 'Il bicchiere è pieno.'),
  (372, 2, 'O baldinho está cheio de areia e conchinhas.', 'The bucket is full of sand and little shells.', 'Der Eimer ist voll mit Sand und kleinen Muscheln.', 'Il secchiello è pieno di sabbia e conchiglie.'),
  (373, 1, 'A caixa está vazia.', 'The box is empty.', 'Die Kiste ist leer.', 'La scatola è vuota.'),
  (373, 2, 'Eu comi tudo e o meu prato ficou vazio.', 'I ate everything and my plate is empty.', 'Ich habe alles aufgegessen und mein Teller ist leer.', 'Ho mangiato tutto e il mio piatto è vuoto.'),
  (374, 1, 'A mão está limpa.', 'The hand is clean.', 'Die Hand ist sauber.', 'La mano è pulita.'),
  (374, 2, 'Depois do banho, o cachorro fica limpo e cheiroso.', 'After its bath, the dog is clean and smells nice.', 'Nach dem Baden ist der Hund sauber und duftet gut.', 'Dopo il bagno il cane è pulito e profumato.'),
  (375, 1, 'O sapato está sujo.', 'The shoe is dirty.', 'Der Schuh ist schmutzig.', 'La scarpa è sporca.'),
  (375, 2, 'O porco fica sujo de lama quando brinca na chuva.', 'The pig gets dirty with mud when it plays in the rain.', 'Das Schwein wird ganz schmutzig, wenn es im Regen im Matsch spielt.', 'Il maiale diventa sporco di fango quando gioca sotto la pioggia.'),
  (376, 1, 'O dia está claro.', 'The day is bright.', 'Der Tag ist hell.', 'La giornata è chiara.'),
  (376, 2, 'Quando eu abro a cortina, o quarto fica claro.', 'When I open the curtain, the room gets bright.', 'Wenn ich den Vorhang aufmache, wird das Zimmer hell.', 'Quando apro la tenda, la camera diventa chiara.'),
  (377, 1, 'A noite é escura.', 'The night is dark.', 'Die Nacht ist dunkel.', 'La notte è scura.'),
  (377, 2, 'A caverna é escura, então a gente leva uma lanterna.', 'The cave is dark, so we bring a flashlight.', 'Die Höhle ist dunkel, also nehmen wir eine Taschenlampe mit.', 'La grotta è buia, quindi portiamo una torcia.'),
  (455, 1, 'O gato está em cima.', 'The cat is on top.', 'Die Katze ist oben.', 'Il gatto è sopra.'),
  (455, 2, 'O gato dorme em cima do armário da cozinha.', 'The cat sleeps on top of the kitchen cupboard.', 'Die Katze schläft oben auf dem Küchenschrank.', 'Il gatto dorme sopra l''armadio della cucina.'),
  (456, 1, 'A bola está embaixo.', 'The ball is under there.', 'Der Ball ist unten.', 'La palla è sotto.'),
  (456, 2, 'O meu chinelo está embaixo da cama.', 'My slipper is under the bed.', 'Mein Hausschuh liegt da unten, unter dem Bett.', 'La mia ciabatta è sotto il letto.'),
  (457, 1, 'O peixe está dentro.', 'The fish is inside.', 'Der Fisch ist drinnen.', 'Il pesce è dentro.'),
  (457, 2, 'Quando chove, a gente brinca dentro de casa.', 'When it rains, we play inside the house.', 'Wenn es regnet, spielen wir drinnen im Haus.', 'Quando piove, giochiamo dentro casa.'),
  (458, 1, 'O cachorro está fora.', 'The dog is outside.', 'Der Hund ist draußen.', 'Il cane è fuori.'),
  (458, 2, 'Quando faz sol, a gente brinca lá fora no quintal.', 'When it''s sunny, we play outside in the yard.', 'Wenn die Sonne scheint, spielen wir draußen im Garten.', 'Quando c''è il sole, giochiamo fuori in cortile.'),
  (459, 1, 'O gato está atrás.', 'The cat is behind.', 'Die Katze ist hinten.', 'Il gatto è dietro.'),
  (459, 2, 'Eu me escondo atrás da árvore no esconde-esconde.', 'I hide behind the tree in hide-and-seek.', 'Beim Verstecken verstecke ich mich hinter dem Baum.', 'A nascondino mi nascondo dietro l''albero.'),
  (460, 1, 'O carro está na frente.', 'The car is in front.', 'Das Auto ist vorne.', 'La macchina è davanti.'),
  (460, 2, 'Na fila, o meu amigo está na frente de mim.', 'In the line, my friend is in front of me.', 'In der Reihe steht mein Freund vor mir.', 'Nella fila il mio amico è davanti a me.'),
  (461, 1, 'Eu sento entre os dois.', 'I sit between the two.', 'Ich sitze zwischen den beiden.', 'Mi siedo tra i due.'),
  (461, 2, 'No sofá, eu sento entre a mamãe e o papai.', 'On the sofa, I sit between Mom and Dad.', 'Auf dem Sofa sitze ich zwischen Mama und Papa.', 'Sul divano mi siedo tra la mamma e papà.'),
  (383, 1, 'O tubarão nada rápido.', 'The shark swims fast.', 'Der Hai schwimmt schnell.', 'Lo squalo nuota veloce.'),
  (383, 2, 'O tubarão tem muitos dentes afiados na boca.', 'The shark has lots of sharp teeth in its mouth.', 'Der Hai hat viele scharfe Zähne im Maul.', 'Lo squalo ha tanti denti aguzzi in bocca.'),
  (384, 1, 'A baleia é enorme.', 'The whale is huge.', 'Der Wal ist riesig.', 'La balena è enorme.'),
  (384, 2, 'A baleia joga água para cima quando respira.', 'The whale sprays water up when it breathes.', 'Der Wal spritzt Wasser in die Luft, wenn er atmet.', 'La balena spruzza acqua in alto quando respira.'),
  (385, 1, 'O polvo tem oito braços.', 'The octopus has eight arms.', 'Der Krake hat acht Arme.', 'Il polpo ha otto tentacoli.'),
  (385, 2, 'O polvo se esconde nas pedras do fundo do mar.', 'The octopus hides among the rocks at the bottom of the sea.', 'Der Krake versteckt sich zwischen den Steinen am Meeresgrund.', 'Il polpo si nasconde tra gli scogli in fondo al mare.'),
  (386, 1, 'O caranguejo anda de lado.', 'The crab walks sideways.', 'Die Krabbe läuft seitwärts.', 'Il granchio cammina di lato.'),
  (386, 2, 'O caranguejo vermelho corre na areia e entra no buraco.', 'The red crab runs across the sand and goes into its hole.', 'Die rote Krabbe läuft über den Sand und verschwindet in ihrem Loch.', 'Il granchio rosso corre sulla sabbia ed entra nella sua buca.'),
  (387, 1, 'A estrela-do-mar é laranja.', 'The starfish is orange.', 'Der Seestern ist orange.', 'La stella marina è arancione.'),
  (387, 2, 'Eu achei uma estrela-do-mar na pedra da praia.', 'I found a starfish on a rock at the beach.', 'Ich habe am Strand einen Seestern auf einem Stein gefunden.', 'Ho trovato una stella marina su uno scoglio in spiaggia.'),
  (388, 1, 'A água-viva é transparente.', 'The jellyfish is see-through.', 'Die Qualle ist durchsichtig.', 'La medusa è trasparente.'),
  (388, 2, 'Cuidado com a água-viva, ela queima a pele.', 'Watch out for the jellyfish, it stings your skin.', 'Vorsicht vor der Qualle, sie brennt auf der Haut.', 'Attenzione alla medusa, punge la pelle.'),
  (389, 1, 'O cavalo-marinho é pequeno.', 'The seahorse is small.', 'Das Seepferdchen ist klein.', 'Il cavalluccio marino è piccolo.'),
  (389, 2, 'O cavalo-marinho segura na alga com o rabo.', 'The seahorse holds on to the seaweed with its tail.', 'Das Seepferdchen hält sich mit dem Schwanz an der Alge fest.', 'Il cavalluccio marino si tiene all''alga con la coda.'),
  (390, 1, 'A foca bate palmas.', 'The seal claps.', 'Die Robbe klatscht.', 'La foca batte le pinne.'),
  (390, 2, 'A foca deita no gelo para tomar sol.', 'The seal lies on the ice to enjoy the sun.', 'Die Robbe liegt auf dem Eis und sonnt sich.', 'La foca si sdraia sul ghiaccio per prendere il sole.'),
  (391, 1, 'A formiga trabalha.', 'The ant works.', 'Die Ameise arbeitet.', 'La formica lavora.'),
  (391, 2, 'A formiga leva a migalha de pão para o formigueiro.', 'The ant carries the bread crumb to the anthill.', 'Die Ameise trägt den Brotkrümel zum Ameisenhaufen.', 'La formica porta la briciola di pane al formicaio.'),
  (392, 1, 'A joaninha é vermelha.', 'The ladybug is red.', 'Der Marienkäfer ist rot.', 'La coccinella è rossa.'),
  (392, 2, 'A joaninha tem bolinhas pretas nas costas.', 'The ladybug has black spots on its back.', 'Der Marienkäfer hat schwarze Punkte auf dem Rücken.', 'La coccinella ha i puntini neri sulla schiena.'),
  (393, 1, 'A aranha faz teia.', 'The spider makes a web.', 'Die Spinne baut ein Netz.', 'Il ragno fa la ragnatela.'),
  (393, 2, 'A aranha espera a mosca no canto da teia.', 'The spider waits for the fly in the corner of its web.', 'Die Spinne wartet in der Ecke ihres Netzes auf die Fliege.', 'Il ragno aspetta la mosca nell''angolo della ragnatela.'),
  (394, 1, 'A minhoca mora na terra.', 'The worm lives in the soil.', 'Der Wurm lebt in der Erde.', 'Il verme vive nella terra.'),
  (394, 2, 'Depois da chuva, a minhoca sai da terra molhada.', 'After the rain, the worm comes out of the wet soil.', 'Nach dem Regen kommt der Wurm aus der nassen Erde.', 'Dopo la pioggia il verme esce dalla terra bagnata.'),
  (395, 1, 'O caracol é lento.', 'The snail is slow.', 'Die Schnecke ist langsam.', 'La lumaca è lenta.'),
  (395, 2, 'O caracol carrega a casinha dele nas costas.', 'The snail carries its little house on its back.', 'Die Schnecke trägt ihr Häuschen auf dem Rücken.', 'La lumaca porta la sua casetta sulla schiena.'),
  (396, 1, 'O besouro é preto.', 'The beetle is black.', 'Der Käfer ist schwarz.', 'Lo scarabeo è nero.'),
  (396, 2, 'O besouro brilhante sobe devagar no tronco da árvore.', 'The shiny beetle slowly climbs up the tree trunk.', 'Der glänzende Käfer krabbelt langsam den Baumstamm hoch.', 'Lo scarabeo lucido sale piano sul tronco dell''albero.'),
  (397, 1, 'A mosca voa.', 'The fly flies.', 'Die Fliege fliegt.', 'La mosca vola.'),
  (397, 2, 'A mosca fica voando em volta do bolo.', 'The fly keeps buzzing around the cake.', 'Die Fliege fliegt immer wieder um den Kuchen herum.', 'La mosca continua a volare intorno alla torta.'),
  (398, 1, 'A lagarta come folhas.', 'The caterpillar eats leaves.', 'Die Raupe frisst Blätter.', 'Il bruco mangia le foglie.'),
  (398, 2, 'A lagarta come muito e depois vira borboleta.', 'The caterpillar eats a lot and then turns into a butterfly.', 'Die Raupe frisst viel und wird dann ein Schmetterling.', 'Il bruco mangia tanto e poi diventa una farfalla.'),
  (406, 1, 'O papagaio fala.', 'The parrot talks.', 'Der Papagei spricht.', 'Il pappagallo parla.'),
  (406, 2, 'O papagaio verde repete tudo o que eu falo.', 'The green parrot repeats everything I say.', 'Der grüne Papagei wiederholt alles, was ich sage.', 'Il pappagallo verde ripete tutto quello che dico.'),
  (407, 1, 'O tucano tem bico grande.', 'The toucan has a big beak.', 'Der Tukan hat einen großen Schnabel.', 'Il tucano ha il becco grande.'),
  (407, 2, 'O tucano come frutas no alto da árvore.', 'The toucan eats fruit high up in the tree.', 'Der Tukan frisst Früchte hoch oben im Baum.', 'Il tucano mangia la frutta in cima all''albero.'),
  (408, 1, 'O pombo come milho.', 'The pigeon eats corn.', 'Die Taube frisst Mais.', 'Il piccione mangia il mais.'),
  (408, 2, 'Os pombos voam todos juntos quando eu corro na praça.', 'The pigeons all fly away together when I run in the square.', 'Die Tauben fliegen alle zusammen weg, wenn ich über den Platz renne.', 'I piccioni volano via tutti insieme quando corro in piazza.'),
  (409, 1, 'O beija-flor é pequeno.', 'The hummingbird is small.', 'Der Kolibri ist klein.', 'Il colibrì è piccolo.'),
  (409, 2, 'O beija-flor bate as asas bem rápido perto da flor.', 'The hummingbird flaps its wings very fast near the flower.', 'Der Kolibri schlägt neben der Blume ganz schnell mit den Flügeln.', 'Il colibrì batte le ali velocissimo vicino al fiore.'),
  (410, 1, 'O cisne é branco.', 'The swan is white.', 'Der Schwan ist weiß.', 'Il cigno è bianco.'),
  (410, 2, 'O cisne nada devagar no lago do parque.', 'The swan swims slowly on the lake in the park.', 'Der Schwan schwimmt langsam auf dem See im Park.', 'Il cigno nuota piano sul lago del parco.'),
  (411, 1, 'O pavão é bonito.', 'The peacock is beautiful.', 'Der Pfau ist schön.', 'Il pavone è bello.'),
  (411, 2, 'O pavão abre a cauda colorida como um leque.', 'The peacock spreads its colorful tail like a fan.', 'Der Pfau schlägt seinen bunten Schwanz wie einen Fächer auf.', 'Il pavone apre la coda colorata come un ventaglio.'),
  (412, 1, 'O galo canta.', 'The rooster crows.', 'Der Hahn kräht.', 'Il gallo canta.'),
  (412, 2, 'O galo canta de manhã cedo e acorda a fazenda.', 'The rooster crows early in the morning and wakes up the farm.', 'Der Hahn kräht früh am Morgen und weckt den ganzen Bauernhof.', 'Il gallo canta di mattina presto e sveglia la fattoria.'),
  (413, 1, 'A águia voa alto.', 'The eagle flies high.', 'Der Adler fliegt hoch.', 'L''aquila vola in alto.'),
  (413, 2, 'A águia faz o ninho no alto da montanha.', 'The eagle builds its nest high up on the mountain.', 'Der Adler baut sein Nest hoch oben auf dem Berg.', 'L''aquila fa il nido in cima alla montagna.'),
  (421, 1, 'Eu jogo futebol.', 'I play soccer.', 'Ich spiele Fußball.', 'Gioco a calcio.'),
  (421, 2, 'No sábado, eu jogo futebol com o papai no parque.', 'On Saturday, I play soccer with Dad in the park.', 'Am Samstag spiele ich mit Papa im Park Fußball.', 'Il sabato gioco a calcio con papà al parco.'),
  (422, 1, 'Eu jogo basquete.', 'I play basketball.', 'Ich spiele Basketball.', 'Gioco a basket.'),
  (422, 2, 'No basquete, eu pulo alto e jogo a bola na cesta.', 'In basketball, I jump high and throw the ball into the hoop.', 'Beim Basketball springe ich hoch und werfe den Ball in den Korb.', 'A basket salto in alto e tiro la palla nel canestro.'),
  (423, 1, 'A raquete é leve.', 'The racket is light.', 'Der Schläger ist leicht.', 'La racchetta è leggera.'),
  (423, 2, 'Eu bato na bolinha com a raquete e ela passa a rede.', 'I hit the little ball with the racket and it goes over the net.', 'Ich schlage den kleinen Ball mit dem Schläger über das Netz.', 'Colpisco la pallina con la racchetta e passa la rete.'),
  (424, 1, 'Eu ando de skate.', 'I ride a skateboard.', 'Ich fahre Skateboard.', 'Vado sullo skateboard.'),
  (424, 2, 'Com capacete na cabeça, eu ando de skate na pista.', 'With a helmet on my head, I ride my skateboard at the skate park.', 'Mit dem Helm auf dem Kopf fahre ich im Skatepark Skateboard.', 'Con il casco in testa vado sullo skateboard alla pista.'),
  (425, 1, 'Eu ando de patins.', 'I go roller skating.', 'Ich fahre Rollschuh.', 'Vado sui pattini.'),
  (425, 2, 'Eu ando de patins no parque segurando a mão da mamãe.', 'I roller skate in the park holding Mom''s hand.', 'Ich fahre im Park Rollschuh und halte Mamas Hand.', 'Vado sui pattini al parco tenendo la mano della mamma.'),
  (426, 1, 'O boxe usa luvas.', 'Boxing uses gloves.', 'Beim Boxen trägt man Handschuhe.', 'Nella boxe si usano i guantoni.'),
  (426, 2, 'No boxe, os lutadores usam luvas grandes e vermelhas.', 'In boxing, the fighters wear big red gloves.', 'Beim Boxen tragen die Kämpfer große rote Handschuhe.', 'Nella boxe i pugili portano grandi guantoni rossi.'),
  (427, 1, 'Eu ganhei uma medalha.', 'I won a medal.', 'Ich habe eine Medaille gewonnen.', 'Ho vinto una medaglia.'),
  (427, 2, 'Quem chega primeiro na corrida ganha a medalha de ouro.', 'Whoever finishes the race first wins the gold medal.', 'Wer beim Rennen zuerst ankommt, gewinnt die Goldmedaille.', 'Chi arriva primo alla corsa vince la medaglia d''oro.'),
  (428, 1, 'O juiz usa o apito.', 'The referee uses the whistle.', 'Der Schiedsrichter benutzt die Pfeife.', 'L''arbitro usa il fischietto.'),
  (428, 2, 'Quando o juiz toca o apito, o jogo começa.', 'When the referee blows the whistle, the game starts.', 'Wenn der Schiedsrichter in die Pfeife pfeift, beginnt das Spiel.', 'Quando l''arbitro suona il fischietto, la partita comincia.'),
  (436, 1, 'O hospital é grande.', 'The hospital is big.', 'Das Krankenhaus ist groß.', 'L''ospedale è grande.'),
  (436, 2, 'No hospital, o médico e a enfermeira cuidam das pessoas.', 'At the hospital, the doctor and the nurse take care of people.', 'Im Krankenhaus kümmern sich der Arzt und die Krankenschwester um die Menschen.', 'All''ospedale il dottore e l''infermiera curano le persone.'),
  (437, 1, 'Eu vou para a escola.', 'I go to school.', 'Ich gehe in die Schule.', 'Vado a scuola.'),
  (437, 2, 'Na escola, eu aprendo as letras e brinco no recreio.', 'At school, I learn my letters and play at recess.', 'In der Schule lerne ich Buchstaben und spiele in der Pause.', 'A scuola imparo le lettere e gioco durante la ricreazione.'),
  (438, 1, 'A igreja tem um sino.', 'The church has a bell.', 'Die Kirche hat eine Glocke.', 'La chiesa ha una campana.'),
  (438, 2, 'O sino da igreja toca no domingo de manhã.', 'The church bell rings on Sunday morning.', 'Am Sonntagmorgen läutet die Glocke der Kirche.', 'La campana della chiesa suona la domenica mattina.'),
  (439, 1, 'O mercado tem frutas.', 'The market has fruit.', 'Auf dem Markt gibt es Obst.', 'Al mercato c''è la frutta.'),
  (439, 2, 'No mercado, a vovó compra maçã, banana e pão.', 'At the market, Grandma buys apples, bananas, and bread.', 'Auf dem Markt kauft Oma Äpfel, Bananen und Brot.', 'Al mercato la nonna compra mele, banane e pane.'),
  (440, 1, 'A padaria tem pão.', 'The bakery has bread.', 'Die Bäckerei hat Brot.', 'Il panificio ha il pane.'),
  (440, 2, 'De manhã, a padaria cheira a pão quentinho.', 'In the morning, the bakery smells of warm bread.', 'Morgens riecht die Bäckerei nach warmem Brot.', 'La mattina il panificio profuma di pane caldo.'),
  (441, 1, 'A farmácia vende remédio.', 'The pharmacy sells medicine.', 'Die Apotheke verkauft Medizin.', 'La farmacia vende le medicine.'),
  (441, 2, 'A mamãe compra um remédio na farmácia da esquina.', 'Mom buys medicine at the pharmacy on the corner.', 'Mama kauft in der Apotheke an der Ecke eine Medizin.', 'La mamma compra una medicina nella farmacia all''angolo.'),
  (442, 1, 'Eu brinco no parque.', 'I play in the park.', 'Ich spiele im Park.', 'Gioco al parco.'),
  (442, 2, 'No parque, eu ando no balanço e no escorregador.', 'At the park, I go on the swing and the slide.', 'Im Park schaukle ich und rutsche die Rutsche runter.', 'Al parco vado sull''altalena e sullo scivolo.'),
  (443, 1, 'O circo chegou.', 'The circus is here.', 'Der Zirkus ist da.', 'È arrivato il circo.'),
  (443, 2, 'No circo, o palhaço e o mágico fazem todo mundo rir.', 'At the circus, the clown and the magician make everyone laugh.', 'Im Zirkus bringen der Clown und der Zauberer alle zum Lachen.', 'Al circo il pagliaccio e il mago fanno ridere tutti.'),
  (448, 1, 'Hoje tem festa.', 'There''s a party today.', 'Heute gibt es eine Party.', 'Oggi c''è una festa.'),
  (448, 2, 'Na minha festa de aniversário tem bolo e balões.', 'At my birthday party there is cake and balloons.', 'Auf meiner Geburtstagsparty gibt es Kuchen und Luftballons.', 'Alla mia festa di compleanno ci sono la torta e i palloncini.'),
  (449, 1, 'Eu sopro a vela.', 'I blow out the candle.', 'Ich puste die Kerze aus.', 'Spengo la candela.'),
  (449, 2, 'O bolo tem uma vela para cada ano que eu fiz.', 'The cake has a candle for every year I''ve turned.', 'Auf dem Kuchen ist eine Kerze für jedes Jahr.', 'Sulla torta c''è una candela per ogni anno che ho compiuto.'),
  (450, 1, 'Eu ganhei um presente.', 'I got a present.', 'Ich habe ein Geschenk bekommen.', 'Ho ricevuto un regalo.'),
  (450, 2, 'O presente tem um laço vermelho e papel colorido.', 'The present has a red bow and colorful paper.', 'Das Geschenk hat eine rote Schleife und buntes Papier.', 'Il regalo ha un fiocco rosso e la carta colorata.'),
  (451, 1, 'O confete é colorido.', 'The confetti is colorful.', 'Das Konfetti ist bunt.', 'I coriandoli sono colorati.'),
  (451, 2, 'No carnaval, a gente joga confete para cima.', 'At carnival, we throw confetti up in the air.', 'Beim Karneval werfen wir Konfetti in die Luft.', 'A carnevale lanciamo i coriandoli in aria.'),
  (452, 1, 'O cupcake é doce.', 'The cupcake is sweet.', 'Der Cupcake ist süß.', 'Il cupcake è dolce.'),
  (452, 2, 'O cupcake tem cobertura rosa e granulado colorido.', 'The cupcake has pink frosting and colorful sprinkles.', 'Der Cupcake hat rosa Glasur und bunte Streusel.', 'Il cupcake ha la glassa rosa e i confettini colorati.'),
  (453, 1, 'O doce é gostoso.', 'The candy is yummy.', 'Das Bonbon ist lecker.', 'La caramella è buona.'),
  (453, 2, 'Depois do almoço, eu posso comer um doce pequeno.', 'After lunch, I can eat a small candy.', 'Nach dem Mittagessen darf ich ein kleines Bonbon essen.', 'Dopo pranzo posso mangiare una caramella piccola.'),
  (454, 1, 'As bandeirinhas são coloridas.', 'The garland is colorful.', 'Die Girlande ist bunt.', 'La ghirlanda è colorata.'),
  (454, 2, 'A gente pendura as bandeirinhas no quintal para a festa.', 'We hang the garland in the yard for the party.', 'Wir hängen die Girlande für die Party im Garten auf.', 'Appendiamo la ghirlanda in cortile per la festa.'),
  (470, 1, 'O martelo é pesado.', 'The hammer is heavy.', 'Der Hammer ist schwer.', 'Il martello è pesante.'),
  (470, 2, 'O vovô usa o martelo para consertar a cadeira.', 'Grandpa uses the hammer to fix the chair.', 'Opa repariert den Stuhl mit dem Hammer.', 'Il nonno usa il martello per riparare la sedia.'),
  (471, 1, 'A chave de fenda gira.', 'The screwdriver turns.', 'Der Schraubenzieher dreht sich.', 'Il cacciavite gira.'),
  (471, 2, 'O papai aperta o parafuso com a chave de fenda.', 'Dad tightens the screw with the screwdriver.', 'Papa dreht die Schraube mit dem Schraubenzieher fest.', 'Papà stringe la vite con il cacciavite.'),
  (472, 1, 'O serrote corta madeira.', 'The saw cuts wood.', 'Die Säge schneidet Holz.', 'La sega taglia il legno.'),
  (472, 2, 'O marceneiro corta a tábua com o serrote.', 'The carpenter cuts the board with the saw.', 'Der Schreiner schneidet das Brett mit der Säge.', 'Il falegname taglia l''asse con la sega.'),
  (473, 1, 'O alicate segura.', 'The pliers hold on.', 'Die Zange hält fest.', 'La pinza tiene stretto.'),
  (473, 2, 'O papai usa o alicate para dobrar o arame.', 'Dad uses the pliers to bend the wire.', 'Papa biegt den Draht mit der Zange.', 'Papà usa la pinza per piegare il filo di ferro.'),
  (474, 1, 'O prego é pontudo.', 'The nail is pointy.', 'Der Nagel ist spitz.', 'Il chiodo è appuntito.'),
  (474, 2, 'O vovô bate o prego na parede para pendurar o quadro.', 'Grandpa hammers the nail into the wall to hang the picture.', 'Opa schlägt den Nagel in die Wand, um das Bild aufzuhängen.', 'Il nonno pianta il chiodo nel muro per appendere il quadro.'),
  (475, 1, 'O parafuso é pequeno.', 'The screw is small.', 'Die Schraube ist klein.', 'La vite è piccola.'),
  (475, 2, 'O meu robô tem um parafuso solto no braço.', 'My robot has a loose screw in its arm.', 'Mein Roboter hat eine lockere Schraube am Arm.', 'Il mio robot ha una vite allentata nel braccio.'),
  (476, 1, 'A furadeira faz barulho.', 'The drill is loud.', 'Der Bohrer ist laut.', 'Il trapano fa rumore.'),
  (476, 2, 'O papai faz um furo na parede com a furadeira.', 'Dad makes a hole in the wall with the drill.', 'Papa bohrt mit dem Bohrer ein Loch in die Wand.', 'Papà fa un buco nel muro con il trapano.'),
  (477, 1, 'A fita métrica mede.', 'The tape measure measures.', 'Das Maßband misst.', 'Il metro misura.'),
  (477, 2, 'O papai mede a janela com a fita métrica.', 'Dad measures the window with the tape measure.', 'Papa misst das Fenster mit dem Maßband.', 'Papà misura la finestra con il metro.'),
  (478, 1, 'A escova de dente é azul.', 'The toothbrush is blue.', 'Die Zahnbürste ist blau.', 'Lo spazzolino è blu.'),
  (478, 2, 'Eu coloco pasta na escova de dente e escovo bem.', 'I put toothpaste on my toothbrush and brush well.', 'Ich tue Zahnpasta auf meine Zahnbürste und putze gründlich.', 'Metto il dentifricio sullo spazzolino e lavo bene i denti.'),
  (479, 1, 'A pasta de dente é branca.', 'The toothpaste is white.', 'Die Zahnpasta ist weiß.', 'Il dentifricio è bianco.'),
  (479, 2, 'A pasta de dente tem gosto de menta.', 'The toothpaste tastes like mint.', 'Die Zahnpasta schmeckt nach Minze.', 'Il dentifricio sa di menta.'),
  (480, 1, 'O sabonete faz espuma.', 'The soap makes foam.', 'Die Seife schäumt.', 'Il sapone fa la schiuma.'),
  (480, 2, 'Eu lavo as mãos com sabonete antes de comer.', 'I wash my hands with soap before eating.', 'Vor dem Essen wasche ich mir die Hände mit Seife.', 'Mi lavo le mani con il sapone prima di mangiare.'),
  (481, 1, 'A toalha é macia.', 'The towel is soft.', 'Das Handtuch ist weich.', 'L''asciugamano è morbido.'),
  (481, 2, 'Depois do banho, eu me enrolo na toalha quentinha.', 'After the bath, I wrap myself in the warm towel.', 'Nach dem Baden wickle ich mich in das warme Handtuch.', 'Dopo il bagno mi avvolgo nell''asciugamano caldo.'),
  (482, 1, 'O shampoo faz bolhas.', 'The shampoo makes bubbles.', 'Das Shampoo macht Blasen.', 'Lo shampoo fa le bolle.'),
  (482, 2, 'A mamãe lava o meu cabelo com shampoo de morango.', 'Mom washes my hair with strawberry shampoo.', 'Mama wäscht meine Haare mit Erdbeershampoo.', 'La mamma mi lava i capelli con lo shampoo alla fragola.'),
  (483, 1, 'Eu uso o pente.', 'I use the comb.', 'Ich benutze den Kamm.', 'Uso il pettine.'),
  (483, 2, 'O vovô penteia o bigode com um pente pequeno.', 'Grandpa combs his mustache with a small comb.', 'Opa kämmt seinen Schnurrbart mit einem kleinen Kamm.', 'Il nonno si pettina i baffi con un pettine piccolo.'),
  (484, 1, 'O chuveiro está quente.', 'The shower is warm.', 'Die Dusche ist warm.', 'La doccia è calda.'),
  (484, 2, 'Eu tomo banho de chuveiro depois de brincar na areia.', 'I take a shower after playing in the sand.', 'Nach dem Spielen im Sand gehe ich unter die Dusche.', 'Faccio la doccia dopo aver giocato nella sabbia.'),
  (485, 1, 'Eu uso o vaso.', 'I use the toilet.', 'Ich benutze die Toilette.', 'Uso il gabinetto.'),
  (485, 2, 'Depois de usar o vaso, eu dou descarga e lavo as mãos.', 'After using the toilet, I flush and wash my hands.', 'Nachdem ich die Toilette benutzt habe, spüle ich und wasche mir die Hände.', 'Dopo aver usato il gabinetto, tiro lo sciacquone e mi lavo le mani.'),
  (494, 1, 'Hoje é segunda.', 'Today is Monday.', 'Heute ist Montag.', 'Oggi è lunedì.'),
  (494, 2, 'Na segunda, eu volto para a escola depois do fim de semana.', 'On Monday, I go back to school after the weekend.', 'Am Montag gehe ich nach dem Wochenende wieder in die Schule.', 'Lunedì torno a scuola dopo il fine settimana.'),
  (495, 1, 'Hoje é terça.', 'Today is Tuesday.', 'Heute ist Dienstag.', 'Oggi è martedì.'),
  (495, 2, 'Na terça, eu tenho aula de natação à tarde.', 'On Tuesday, I have swimming class in the afternoon.', 'Am Dienstag habe ich nachmittags Schwimmunterricht.', 'Martedì ho lezione di nuoto il pomeriggio.'),
  (496, 1, 'Hoje é quarta.', 'Today is Wednesday.', 'Heute ist Mittwoch.', 'Oggi è mercoledì.'),
  (496, 2, 'Na quarta, a vovó vem almoçar com a gente.', 'On Wednesday, Grandma comes to have lunch with us.', 'Am Mittwoch kommt Oma zum Mittagessen zu uns.', 'Mercoledì la nonna viene a pranzo da noi.'),
  (497, 1, 'Hoje é quinta.', 'Today is Thursday.', 'Heute ist Donnerstag.', 'Oggi è giovedì.'),
  (497, 2, 'Na quinta, eu levo um livro da biblioteca para casa.', 'On Thursday, I take a library book home.', 'Am Donnerstag nehme ich ein Buch aus der Bücherei mit nach Hause.', 'Giovedì porto a casa un libro della biblioteca.'),
  (498, 1, 'Hoje é sexta.', 'Today is Friday.', 'Heute ist Freitag.', 'Oggi è venerdì.'),
  (498, 2, 'Na sexta à noite, a família come pizza e assiste a um filme.', 'On Friday night, the family eats pizza and watches a movie.', 'Am Freitagabend isst die Familie Pizza und schaut einen Film.', 'Venerdì sera la famiglia mangia la pizza e guarda un film.'),
  (499, 1, 'Hoje é sábado.', 'Today is Saturday.', 'Heute ist Samstag.', 'Oggi è sabato.'),
  (499, 2, 'No sábado, eu não vou à escola e brinco no parque.', 'On Saturday, I don''t go to school and I play in the park.', 'Am Samstag gehe ich nicht in die Schule und spiele im Park.', 'Sabato non vado a scuola e gioco al parco.'),
  (500, 1, 'Hoje é domingo.', 'Today is Sunday.', 'Heute ist Sonntag.', 'Oggi è domenica.'),
  (500, 2, 'No domingo, a família toda almoça na casa do vovô.', 'On Sunday, the whole family has lunch at Grandpa''s house.', 'Am Sonntag isst die ganze Familie bei Opa zu Mittag.', 'Domenica tutta la famiglia pranza a casa del nonno.'),
  (501, 1, 'Eu durmo no quarto.', 'I sleep in the bedroom.', 'Ich schlafe im Schlafzimmer.', 'Dormo in camera.'),
  (501, 2, 'No meu quarto tem uma cama, uma estante e muitos brinquedos.', 'In my bedroom there''s a bed, a bookshelf, and lots of toys.', 'In meinem Schlafzimmer stehen ein Bett, ein Bücherregal und viele Spielsachen.', 'Nella mia camera ci sono un letto, uno scaffale e tanti giocattoli.'),
  (502, 1, 'A sala tem um sofá.', 'The living room has a sofa.', 'Im Wohnzimmer steht ein Sofa.', 'In soggiorno c''è un divano.'),
  (502, 2, 'A família assiste televisão junta na sala.', 'The family watches TV together in the living room.', 'Die Familie schaut zusammen im Wohnzimmer fern.', 'La famiglia guarda la televisione insieme in soggiorno.'),
  (503, 1, 'O papai está na cozinha.', 'Dad is in the kitchen.', 'Papa ist in der Küche.', 'Papà è in cucina.'),
  (503, 2, 'Na cozinha, a vovó faz bolo e o cheiro é delicioso.', 'In the kitchen, Grandma bakes a cake and it smells delicious.', 'In der Küche backt Oma einen Kuchen und es riecht köstlich.', 'In cucina la nonna fa la torta e c''è un profumo buonissimo.'),
  (504, 1, 'Eu escovo os dentes no banheiro.', 'I brush my teeth in the bathroom.', 'Ich putze mir im Badezimmer die Zähne.', 'Mi lavo i denti in bagno.'),
  (504, 2, 'No banheiro, eu tomo banho com o meu patinho de borracha.', 'In the bathroom, I take a bath with my rubber duck.', 'Im Badezimmer bade ich mit meiner Gummiente.', 'In bagno faccio il bagnetto con la mia paperella di gomma.'),
  (505, 1, 'O carro está na garagem.', 'The car is in the garage.', 'Das Auto steht in der Garage.', 'La macchina è in garage.'),
  (505, 2, 'Na garagem, o papai guarda o carro e as bicicletas.', 'In the garage, Dad keeps the car and the bicycles.', 'In der Garage stellt Papa das Auto und die Fahrräder ab.', 'In garage papà tiene la macchina e le biciclette.'),
  (506, 1, 'O jardim tem flores.', 'The garden has flowers.', 'Im Garten sind Blumen.', 'Il giardino ha i fiori.'),
  (506, 2, 'No jardim, eu rego as plantas e vejo as borboletas.', 'In the garden, I water the plants and watch the butterflies.', 'Im Garten gieße ich die Pflanzen und schaue den Schmetterlingen zu.', 'In giardino annaffio le piante e guardo le farfalle.'),
  (507, 1, 'A mamãe trabalha no escritório.', 'Mom works in the office.', 'Mama arbeitet im Büro.', 'La mamma lavora in ufficio.'),
  (507, 2, 'No escritório tem um computador, papéis e muitas canetas.', 'In the office there''s a computer, papers, and lots of pens.', 'Im Büro gibt es einen Computer, Papiere und viele Stifte.', 'In ufficio ci sono un computer, dei fogli e tante penne.'),
  (508, 1, 'A roupa está na lavanderia.', 'The clothes are in the laundry room.', 'Die Wäsche ist in der Waschküche.', 'I vestiti sono in lavanderia.'),
  (508, 2, 'Na lavanderia, a máquina lava as roupas sujas.', 'In the laundry room, the machine washes the dirty clothes.', 'In der Waschküche wäscht die Maschine die schmutzige Wäsche.', 'In lavanderia la lavatrice lava i vestiti sporchi.'),
  (529, 1, 'A girafa é alta.', 'The giraffe is tall.', 'Die Giraffe ist sehr groß.', 'La giraffa è alta.'),
  (529, 2, 'O papai é alto e consegue pegar o livro na prateleira.', 'Dad is tall and can reach the book on the shelf.', 'Papa ist groß und kommt an das Buch im Regal heran.', 'Papà è alto e riesce a prendere il libro sulla mensola.'),
  (530, 1, 'A cerca é baixa.', 'The fence is low.', 'Der Zaun ist niedrig.', 'Il recinto è basso.'),
  (530, 2, 'A mesinha é baixa, do tamanho certo para mim.', 'The little table is low, just the right size for me.', 'Der kleine Tisch ist niedrig, genau richtig für mich.', 'Il tavolino è basso, proprio della mia misura.'),
  (535, 1, 'O carro é rápido.', 'The car is fast.', 'Das Auto ist schnell.', 'La macchina è veloce.'),
  (535, 2, 'O guepardo é o animal mais rápido de todos.', 'The cheetah is the fastest animal of all.', 'Der Gepard ist das schnellste Tier von allen.', 'Il ghepardo è l''animale più veloce di tutti.'),
  (536, 1, 'A tartaruga é lenta.', 'The turtle is slow.', 'Die Schildkröte ist langsam.', 'La tartaruga è lenta.'),
  (536, 2, 'O caracol é lento, mas sempre chega no fim.', 'The snail is slow, but it always gets to the end.', 'Die Schnecke ist langsam, aber sie kommt immer ans Ziel.', 'La lumaca è lenta, ma arriva sempre alla fine.'),
  (541, 1, 'O sapato é novo.', 'The shoe is new.', 'Der Schuh ist neu.', 'La scarpa è nuova.'),
  (541, 2, 'Eu ganhei uma bicicleta nova no meu aniversário.', 'I got a new bicycle for my birthday.', 'Ich habe zum Geburtstag ein neues Fahrrad bekommen.', 'Per il mio compleanno ho ricevuto una bicicletta nuova.'),
  (542, 1, 'O livro é velho.', 'The book is old.', 'Das Buch ist alt.', 'Il libro è vecchio.'),
  (542, 2, 'O vovô tem um carro velho que ainda funciona.', 'Grandpa has an old car that still works.', 'Opa hat ein altes Auto, das noch fährt.', 'Il nonno ha una macchina vecchia che funziona ancora.'),
  (547, 1, 'A pedra é dura.', 'The stone is hard.', 'Der Stein ist hart.', 'La pietra è dura.'),
  (547, 2, 'O coco é duro por fora e macio por dentro.', 'The coconut is hard outside and soft inside.', 'Die Kokosnuss ist außen hart und innen weich.', 'Il cocco è duro fuori e morbido dentro.'),
  (548, 1, 'O travesseiro é mole.', 'The pillow is soft.', 'Das Kissen ist weich.', 'Il cuscino è morbido.'),
  (548, 2, 'A massinha de modelar é mole e muda de forma.', 'The play dough is soft and changes shape.', 'Die Knete ist weich und verändert ihre Form.', 'La pasta da modellare è morbida e cambia forma.'),
  (558, 1, 'A chaleira apita.', 'The kettle whistles.', 'Der Kessel pfeift.', 'Il bollitore fischia.'),
  (558, 2, 'Quando a água ferve, a chaleira apita bem alto.', 'When the water boils, the kettle whistles really loudly.', 'Wenn das Wasser kocht, pfeift der Kessel ganz laut.', 'Quando l''acqua bolle, il bollitore fischia fortissimo.'),
  (559, 1, 'A concha serve a sopa.', 'The ladle serves the soup.', 'Mit der Kelle schöpft man die Suppe.', 'Il mestolo serve la zuppa.'),
  (559, 2, 'A vovó usa a concha para colocar sopa no meu prato.', 'Grandma uses the ladle to put soup on my plate.', 'Oma füllt mir mit der Kelle Suppe auf den Teller.', 'La nonna usa il mestolo per mettere la zuppa nel mio piatto.'),
  (560, 1, 'O ralador rala o queijo.', 'The grater grates the cheese.', 'Die Reibe reibt den Käse.', 'La grattugia gratta il formaggio.'),
  (560, 2, 'O papai rala queijo no ralador para o macarrão.', 'Dad grates cheese on the grater for the pasta.', 'Papa reibt mit der Reibe Käse für die Nudeln.', 'Papà grattugia il formaggio per la pasta.'),
  (561, 1, 'A peneira tem furinhos.', 'The sieve has tiny holes.', 'Das Sieb hat kleine Löcher.', 'Il setaccio ha tanti buchini.'),
  (561, 2, 'A mamãe passa a farinha na peneira para fazer bolo.', 'Mom sifts the flour through the sieve to make a cake.', 'Mama siebt das Mehl durch das Sieb, um einen Kuchen zu backen.', 'La mamma passa la farina nel setaccio per fare la torta.'),
  (563, 1, 'A tábua é de madeira.', 'The board is made of wood.', 'Das Brett ist aus Holz.', 'Il tagliere è di legno.'),
  (563, 2, 'O papai corta as frutas em cima da tábua.', 'Dad cuts the fruit on the board.', 'Papa schneidet das Obst auf dem Brett.', 'Papà taglia la frutta sul tagliere.'),
  (564, 1, 'O rolo abre a massa.', 'The rolling pin rolls out the dough.', 'Das Nudelholz rollt den Teig aus.', 'Il mattarello stende la pasta.'),
  (564, 2, 'Eu passo o rolo na massa para fazer biscoitos.', 'I roll the rolling pin over the dough to make cookies.', 'Ich rolle den Teig mit dem Nudelholz aus, um Kekse zu machen.', 'Passo il mattarello sulla pasta per fare i biscotti.'),
  (565, 1, 'O batedor mexe rápido.', 'The whisk stirs fast.', 'Der Schneebesen rührt schnell.', 'La frusta gira veloce.'),
  (565, 2, 'Eu bato os ovos com o batedor para fazer bolo.', 'I beat the eggs with the whisk to make a cake.', 'Ich schlage die Eier mit dem Schneebesen für den Kuchen.', 'Sbatto le uova con la frusta per fare la torta.'),
  (566, 1, 'O avental é bonito.', 'The apron is pretty.', 'Die Schürze ist schön.', 'Il grembiule è bello.'),
  (566, 2, 'Eu coloco o avental para não sujar a roupa na cozinha.', 'I put on the apron so I don''t get my clothes dirty in the kitchen.', 'Ich ziehe die Schürze an, damit meine Kleidung in der Küche sauber bleibt.', 'Mi metto il grembiule per non sporcare i vestiti in cucina.'),
  (567, 1, 'A luva protege a mão.', 'The oven mitt protects my hand.', 'Der Topfhandschuh schützt die Hand.', 'Il guanto da forno protegge la mano.'),
  (567, 2, 'A mamãe usa a luva para tirar o bolo quente do forno.', 'Mom uses the oven mitt to take the hot cake out of the oven.', 'Mama nimmt den heißen Kuchen mit dem Topfhandschuh aus dem Ofen.', 'La mamma usa il guanto da forno per tirare fuori la torta calda.'),
  (568, 1, 'O bule tem chá.', 'The teapot has tea in it.', 'In der Teekanne ist Tee.', 'Nella teiera c''è il tè.'),
  (568, 2, 'A vovó serve o chá do bule nas xícaras.', 'Grandma pours tea from the teapot into the cups.', 'Oma gießt den Tee aus der Teekanne in die Tassen.', 'La nonna versa il tè dalla teiera nelle tazze.');
